import { NextResponse, type NextRequest } from "next/server";
import { and, eq } from "drizzle-orm";
import { db } from "@/db";
import { scripts } from "@/db/schema";
import { getCurrentUser } from "@/lib/session";
import { renderUserScript } from "@/lib/scripts";
import { sha256 } from "@/lib/auth";

export const dynamic = "force-dynamic";

function slugify(value: string): string {
  return (
    value
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60) || "script"
  );
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

  const { id } = await ctx.params;
  const scriptId = Number.parseInt(id, 10);
  if (!Number.isFinite(scriptId)) {
    return NextResponse.json({ error: "ID invalido" }, { status: 400 });
  }

  const script = (
    await db
      .select()
      .from(scripts)
      .where(and(eq(scripts.id, scriptId), eq(scripts.userId, user.id)))
      .limit(1)
  )[0];

  if (!script) return NextResponse.json({ error: "No encontrado" }, { status: 404 });

  const wantsObfuscated =
    req.nextUrl.searchParams.get("obfuscate") === "1" || script.obfuscateByDefault;

  const origin = req.nextUrl.origin;
  const installUrl = `${origin}/api/scripts/${script.id}/download`;
  const output = renderUserScript(
    {
      ...script,
      updateUrl: script.updateUrl || installUrl,
      downloadUrl: script.downloadUrl || installUrl,
    },
    wantsObfuscated,
  );

  return new NextResponse(output, {
    status: 200,
    headers: {
      "content-type": "text/javascript; charset=utf-8",
      "content-disposition": `attachment; filename="${slugify(script.name)}-${
        script.version
      }.user.js"`,
      "x-script-hash": sha256(output).slice(0, 16),
      "cache-control": "no-store",
    },
  });
}

src/app/api/scripts/[id]/route.ts:
import { NextResponse, type NextRequest } from "next/server";
import { and, eq } from "drizzle-orm";
import { db } from "@/db";
import { scripts } from "@/db/schema";
import { getCurrentUser } from "@/lib/session";
import {
  fetchRemoteCode,
  normalizeScriptInput,
  scriptHash,
} from "@/lib/scripts";

export const dynamic = "force-dynamic";

type Ctx = { params: Promise<{ id: string }> };

async function loadScript(userId: number, rawId: string) {
  const id = Number.parseInt(rawId, 10);
  if (!Number.isFinite(id)) return null;
  const row = (
    await db
      .select()
      .from(scripts)
      .where(and(eq(scripts.id, id), eq(scripts.userId, userId)))
      .limit(1)
  )[0];
  return row ?? null;
}

export async function GET(_req: NextRequest, ctx: Ctx) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

  const { id } = await ctx.params;
  const script = await loadScript(user.id, id);
  if (!script) return NextResponse.json({ error: "No encontrado" }, { status: 404 });

  return NextResponse.json({ script });
}

export async function PATCH(req: NextRequest, ctx: Ctx) {
  try {
    const user = await getCurrentUser();
    if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

    const { id } = await ctx.params;
    const script = await loadScript(user.id, id);
    if (!script) return NextResponse.json({ error: "No encontrado" }, { status: 404 });

    const body = await req.json().catch(() => ({}));
    const input = normalizeScriptInput({ ...script, ...body });

    let code = input.code;
    const refetch = body.refetchFromSource === true;
    if (refetch && input.sourceUrl) {
      const remote = await fetchRemoteCode(input.sourceUrl);
      if (!remote.ok) {
        return NextResponse.json(
          { error: `No se pudo reimportar: ${remote.error}` },
          { status: 400 },
        );
      }
      code = remote.code;
    }

    const updated = await db
      .update(scripts)
      .set({
        ...input,
        code,
        codeHash: scriptHash(code),
        updatedAt: new Date(),
      })
      .where(eq(scripts.id, script.id))
      .returning();

    return NextResponse.json({ script: updated[0] });
  } catch (error) {
    console.error("[scripts PATCH]", error);
    return NextResponse.json({ error: "No se pudo actualizar" }, { status: 500 });
  }
}

export async function DELETE(_req: NextRequest, ctx: Ctx) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

  const { id } = await ctx.params;
  const script = await loadScript(user.id, id);
  if (!script) return NextResponse.json({ error: "No encontrado" }, { status: 404 });

  await db.delete(scripts).where(eq(scripts.id, script.id));
  return NextResponse.json({ success: true });
}

import { NextResponse, type NextRequest } from "next/server";
import { and, eq, inArray } from "drizzle-orm";
import { db } from "@/db";
import { scripts } from "@/db/schema";
import { getCurrentUser } from "@/lib/session";
import { fetchRemoteCode, scriptHash } from "@/lib/scripts";

export const dynamic = "force-dynamic";

type UpdateResult = {
  id: number;
  name: string;
  status: "updated" | "unchanged" | "error" | "skipped";
  detail?: string;
  oldHash?: string;
  newHash?: string;
};

export async function POST(req: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

    const body = (await req.json().catch(() => ({}))) as { scriptIds?: unknown };
    const requested = Array.isArray(body.scriptIds)
      ? body.scriptIds.map((v) => Number(v)).filter((v) => Number.isFinite(v))
      : [];

    const rows = requested.length
      ? await db
          .select()
          .from(scripts)
          .where(and(eq(scripts.userId, user.id), inArray(scripts.id, requested)))
      : await db.select().from(scripts).where(eq(scripts.userId, user.id));

    const results: UpdateResult[] = [];

    for (const script of rows) {
      if (!script.sourceUrl) {
        results.push({
          id: script.id,
          name: script.name,
          status: "skipped",
          detail: "Sin URL de origen",
        });
        continue;
      }

      const remote = await fetchRemoteCode(script.sourceUrl);
      if (!remote.ok) {
        results.push({
          id: script.id,
          name: script.name,
          status: "error",
          detail: remote.error,
        });
        continue;
      }

      const newHash = scriptHash(remote.code);
      if (newHash === script.codeHash) {
        await db
          .update(scripts)
          .set({ lastCheckAt: new Date() })
          .where(eq(scripts.id, script.id));
        results.push({ id: script.id, name: script.name, status: "unchanged", newHash });
        continue;
      }

      await db
        .update(scripts)
        .set({
          code: remote.code,
          codeHash: newHash,
          lastCheckAt: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(scripts.id, script.id));

      results.push({
        id: script.id,
        name: script.name,
        status: "updated",
        oldHash: script.codeHash,
        newHash,
      });
    }

    return NextResponse.json({
      checked: rows.length,
      updates: results.filter((r) => r.status === "updated").length,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error("[check-updates POST]", error);
    return NextResponse.json({ error: "Error verificando actualizaciones" }, { status: 500 });
  }
}

export async function GET(req: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) return NextResponse.json({ error: "No autenticado" }, { status: 401 });

    const rawId = req.nextUrl.searchParams.get("id");
    const scriptId = Number.parseInt(rawId ?? "", 10);
    if (!Number.isFinite(scriptId)) {
      return NextResponse.json({ error: "ID de script requerido" }, { status: 400 });
    }

    const script = (
      await db
        .select()
        .from(scripts)
        .where(and(eq(scripts.id, scriptId), eq(scripts.userId, user.id)))
        .limit(1)
    )[0];

    if (!script) return NextResponse.json({ error: "No encontrado" }, { status: 404 });
    if (!script.sourceUrl) {
      return NextResponse.json(
        { error: "El script no tiene URL de origen" },
        { status: 400 },
      );
    }

    const remote = await fetchRemoteCode(script.sourceUrl);
    if (!remote.ok) {
      return NextResponse.json({ error: remote.error }, { status: 502 });
    }

    const newHash = scriptHash(remote.code);
    const hasUpdate = newHash !== script.codeHash;

    if (hasUpdate) {
      await db
        .update(scripts)
        .set({
          code: remote.code,
          codeHash: newHash,
          lastCheckAt: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(scripts.id, script.id));
    } else {
      await db
        .update(scripts)
        .set({ lastCheckAt: new Date() })
        .where(eq(scripts.id, script.id));
    }

    return NextResponse.json({
      id: script.id,
      name: script.name,
      hasUpdate,
      oldHash: script.codeHash,
      newHash,
      newCodeSize: remote.code.length,
      lastCheck: new Date().toISOString(),
    });
  } catch (error) {
    console.error("[check-updates GET]", error);
    return NextResponse.json({ error: "Error en la solicitud" }, { status: 500 });
  }
}

