"use client";

import { useState } from "react";

export function CopyButton({ path, label = "Copiar" }: { path: string; label?: string }) {
  const [state, setState] = useState<"idle" | "loading" | "done" | "error">("idle");

  async function copy() {
    setState("loading");
    try {
      const res = await fetch(`/api/download?path=${encodeURIComponent(path)}&raw=1`, {
        cache: "no-store",
      });
      if (!res.ok) throw new Error("fetch failed");
      const text = await res.text();
      await navigator.clipboard.writeText(text);
      setState("done");
    } catch {
      setState("error");
    } finally {
      setTimeout(() => setState("idle"), 1800);
    }
  }

  const text =
    state === "loading"
      ? "Copiando..."
      : state === "done"
        ? "Copiado"
        : state === "error"
          ? "Error"
          : label;

  return (
    <button
      onClick={copy}
      className="rounded-md border border-slate-700 px-2.5 py-1 text-xs text-slate-300 transition hover:border-emerald-500 hover:text-emerald-300"
    >
      {text}
    </button>
  );
}

src/components/pin-login.tsx:
"use client";

import { useEffect, useState, type FormEvent } from "react";

type Mode = "pin" | "locked" | "password" | "success";

export function PinLogin() {
  const [pin, setPin] = useState("");
  const [password, setPassword] = useState("");
  const [mode, setMode] = useState<Mode>("pin");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [lockTimeLeft, setLockTimeLeft] = useState(0);

  useEffect(() => {
    if (lockTimeLeft <= 0) return;
    const timer = setInterval(() => setLockTimeLeft((prev) => Math.max(0, prev - 1)), 1000);
    return () => clearInterval(timer);
  }, [lockTimeLeft]);

  async function submit(payload: Record<string, unknown>) {
    setError("");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/pin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = (await res.json().catch(() => ({}))) as {
        error?: string;
        requiresPassword?: boolean;
        unlockTime?: number;
      };

      if (res.ok) {
        setMode("success");
        setTimeout(() => window.location.assign("/dashboard"), 700);
        return;
      }

      if (data.requiresPassword) {
        setMode("password");
        if (data.unlockTime && data.unlockTime > 0) setLockTimeLeft(data.unlockTime);
      }
      setError(data.error ?? "No se pudo validar el acceso");
    } catch {
      setError("Error de conexion con el servidor");
    } finally {
      setLoading(false);
    }
  }

  function onPinSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void submit({ pin, requirePassword: false });
  }

  function onPasswordSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void submit({ pin, requirePassword: true, password });
  }

  if (mode === "success") {
    return (
      <div className="w-full rounded-2xl border border-emerald-800 bg-emerald-950/70 p-8 text-center">
        <h1 className="text-2xl font-bold text-emerald-100">Acceso valido</h1>
        <p className="mt-2 text-emerald-300">Redirigiendo al boveda...</p>
      </div>
    );
  }

  return (
    <div className="w-full rounded-2xl border border-slate-800 bg-slate-900/80 p-8 shadow-2xl backdrop-blur">
      <h1 className="text-3xl font-bold text-white">Tampervault</h1>
      <p className="mt-1 text-sm text-slate-400">
        {mode === "password"
          ? "Bloqueo activo: ingresa tu contrasena para continuar"
          : "Boveda privada de userscripts"}
      </p>

      {mode === "pin" ? (
        <form onSubmit={onPinSubmit} className="mt-8 space-y-4">
          <label className="block text-sm font-medium text-slate-300" htmlFor="pin">
            PIN de acceso (6 digitos)
          </label>
          <input
            id="pin"
            type="password"
            inputMode="numeric"
            autoComplete="off"
            placeholder="000000"
            value={pin}
            onChange={(e) => setPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
            maxLength={6}
            required
            disabled={loading}
            className="w-full rounded-lg border border-slate-700 bg-slate-800 px-4 py-3 text-center text-2xl tracking-[0.5em] text-white focus:border-emerald-500 focus:outline-none disabled:opacity-50"
          />

          {error && (
            <p className="rounded-lg border border-red-800 bg-red-950/60 p-3 text-sm text-red-200">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={loading || pin.length !== 6}
            className="w-full rounded-lg bg-emerald-600 py-2.5 font-semibold text-white transition hover:bg-emerald-500 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? "Verificando..." : "Ingresar"}
          </button>
        </form>
      ) : (
        <form onSubmit={onPasswordSubmit} className="mt-8 space-y-4">
          {lockTimeLeft > 0 && (
            <p className="rounded-lg border border-amber-800 bg-amber-950/50 p-3 text-sm text-amber-200">
              Bloqueado. Espera {lockTimeLeft}s o usa tu contrasena.
            </p>
          )}

          <input
            type="password"
            autoComplete="current-password"
            placeholder="Contrasena de recuperacion"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            maxLength={80}
            required
            disabled={loading}
            className="w-full rounded-lg border border-slate-700 bg-slate-800 px-4 py-2.5 text-white focus:border-emerald-500 focus:outline-none disabled:opacity-50"
          />

          {error && <p className="text-sm text-red-400">{error}</p>}

          <button
            type="submit"
            disabled={loading}
            className="w-full rounded-lg bg-emerald-600 py-2.5 font-semibold text-white transition hover:bg-emerald-500 disabled:opacity-50"
          >
            {loading ? "Verificando..." : "Desbloquear"}
          </button>

          <button
            type="button"
            onClick={() => {
              setMode("pin");
              setError("");
              setPassword("");
            }}
            className="w-full text-xs text-slate-400 underline hover:text-slate-200"
          >
            Volver al PIN
          </button>
        </form>
      )}

      <p className="mt-8 border-t border-slate-800 pt-4 text-xs leading-relaxed text-slate-500">
        <strong className="text-slate-400">Politica de seguridad:</strong> 3 intentos de
        PIN, bloqueo de 5 minutos y despues contrasena obligatoria durante 10 minutos.
      </p>
    </div>
  );
}

src/components/script-manager.tsx:
"use client";

import { useMemo, useState } from "react";

export type ScriptRow = {
  id: number;
  name: string;
  namespace: string;
  version: string;
  description: string;
  author: string;
  matches: string[];
  grants: string[];
  runAt: string;
  updateUrl: string;
  downloadUrl: string;
  code: string;
  codeHash: string;
  sourceUrl: string | null;
  obfuscateByDefault: boolean;
  lastCheckAt: string | null;
  createdAt: string;
  updatedAt: string;
};

const emptyForm = {
  name: "",
  version: "1.0.0",
  description: "",
  author: "",
  matches: "",
  grants: "GM_addStyle",
  runAt: "document-idle",
  sourceUrl: "",
  code: `// ==UserScript==\n// ==/UserScript==\n\n(function () {\n  "use strict";\n})();\n`,
  obfuscateByDefault: false,
};

export function ScriptManager({
  username,
  initialScripts,
}: {
  username: string;
  initialScripts: ScriptRow[];
}) {
  const [items, setItems] = useState<ScriptRow[]>(initialScripts);
  const [form, setForm] = useState({ ...emptyForm });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [pinForm, setPinForm] = useState({ currentPassword: "", newPin: "", newPassword: "" });

  const stats = useMemo(
    () => ({
      total: items.length,
      withSource: items.filter((s) => s.sourceUrl).length,
      obfuscated: items.filter((s) => s.obfuscateByDefault).length,
      bytes: items.reduce((acc, s) => acc + s.code.length, 0),
    }),
    [items],
  );

  async function call(url: string, init?: RequestInit) {
    setBusy(true);
    setMessage("");
    try {
      const res = await fetch(url, {
        ...init,
        headers: init?.body ? { "Content-Type": "application/json" } : undefined,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error((data as { error?: string }).error ?? "Error");
      return data as Record<string, unknown>;
    } finally {
      setBusy(false);
    }
  }

  async function reload() {
    const data = await call("/api/scripts");
    setItems((data.scripts as ScriptRow[]) ?? []);
  }

  async function save() {
    try {
      if (editingId) {
        await call(`/api/scripts/${editingId}`, { method: "PATCH", body: JSON.stringify(form) });
        setMessage("Script actualizado");
      } else {
        await call("/api/scripts", { method: "POST", body: JSON.stringify(form) });
        setMessage("Script creado");
      }
      setForm({ ...emptyForm });
      setEditingId(null);
      await reload();
    } catch (error) {
      setMessage((error as Error).message);
    }
  }

  async function remove(id: number) {
    if (!confirm("Eliminar este script de la boveda?")) return;
    await call(`/api/scripts/${id}`, { method: "DELETE" });
    await reload();
    setMessage("Script eliminado");
  }

  async function edit(id: number) {
    const data = await call(`/api/scripts/${id}`);
    const script = data.script as ScriptRow;
    setEditingId(id);
    setForm({
      name: script.name,
      version: script.version,
      description: script.description,
      author: script.author,
      matches: script.matches.join("\n"),
      grants: script.grants.join("\n"),
      runAt: script.runAt,
      sourceUrl: script.sourceUrl ?? "",
      code: script.code,
      obfuscateByDefault: script.obfuscateByDefault,
    });
  }

  async function checkAll() {
    const data = await call("/api/scripts/check-updates", { method: "POST", body: "{}" });
    const updates = Number(data.updates ?? 0);
    setMessage(
      `${data.checked} revisados · ${updates} actualizados · ${
        (data.results as { status: string }[]).filter((r) => r.status === "error").length
      } errores`,
    );
    await reload();
  }

  async function logout() {
    await fetch("/api/auth/logout", { method: "POST" });
    window.location.assign("/");
  }

  async function saveCredentials() {
    try {
      await call("/api/auth/credentials", { method: "POST", body: JSON.stringify(pinForm) });
      setMessage("Credenciales actualizadas");
      setPinForm({ currentPassword: "", newPin: "", newPassword: "" });
    } catch (error) {
      setMessage((error as Error).message);
    }
  }

  const input =
    "w-full rounded-lg border border-slate-700 bg-slate-900 px-3 py-2 text-sm text-slate-100 focus:border-emerald-500 focus:outline-none";

  return (
    <div className="space-y-8">
      <header className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Boveda de {username}</h1>
          <p className="text-sm text-slate-400">
            {stats.total} scripts · {stats.withSource} con origen remoto · {stats.obfuscated}{" "}
            ofuscados · {(stats.bytes / 1024).toFixed(1)} KB
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={checkAll}
            disabled={busy}
            className="rounded-lg bg-sky-600 px-4 py-2 text-sm font-semibold hover:bg-sky-500 disabled:opacity-50"
          >
            Buscar actualizaciones
          </button>
          <button
            onClick={logout}
            className="rounded-lg border border-slate-700 px-4 py-2 text-sm hover:bg-slate-800"
          >
            Salir
          </button>
        </div>
      </header>

      {message && (
        <p className="rounded-lg border border-emerald-800 bg-emerald-950/50 p-3 text-sm text-emerald-200">
          {message}
        </p>
      )}

      <section className="grid gap-6 lg:grid-cols-[1.1fr_0.9fr]">
        <div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5">
          <h2 className="mb-4 font-semibold">
            {editingId ? `Editando script #${editingId}` : "Nuevo script"}
          </h2>
          <div className="grid gap-3 sm:grid-cols-2">
            <input
              className={input}
              placeholder="Nombre"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
            <input
              className={input}
              placeholder="Version"
              value={form.version}
              onChange={(e) => setForm({ ...form, version: e.target.value })}
            />
            <input
              className={input}
              placeholder="Autor"
              value={form.author}
              onChange={(e) => setForm({ ...form, author: e.target.value })}
            />
            <select
              className={input}
              value={form.runAt}
              onChange={(e) => setForm({ ...form, runAt: e.target.value })}
            >
              {["document-start", "document-body", "document-end", "document-idle"].map((v) => (
                <option key={v} value={v}>
                  {v}
                </option>
              ))}
            </select>
            <textarea
              className={`${input} sm:col-span-2`}
              rows={2}
              placeholder="Descripción"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
            />
            <textarea
              className={`${input} sm:col-span-2`}
              rows={2}
              placeholder="@match, uno por linea"
              value={form.matches}
              onChange={(e) => setForm({ ...form, matches: e.target.value })}
            />
            <textarea
              className={`${input} sm:col-span-2`}
              rows={2}
              placeholder="@grant, uno por linea"
              value={form.grants}
              onChange={(e) => setForm({ ...form, grants: e.target.value })}
            />
            <input
              className={`${input} sm:col-span-2`}
              placeholder="URL de origen (opcional, se sincroniza)"
              value={form.sourceUrl}
              onChange={(e) => setForm({ ...form, sourceUrl: e.target.value })}
            />
            <textarea
              className={`${input} sm:col-span-2`}
              rows={10}
