            {items.length === 0 && (
              <tr>
                <td className="p-6 text-center text-slate-500" colSpan={5}>
                  Todavia no hay scripts guardados.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </section>
    </div>
  );
