 "scripts/init-db.mjs": "import "dotenv/config";
import pg from "pg";

const { Client } = pg;

const SQL = `
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  pin_hash TEXT,
  totp_secret TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sessions (
  id SERIAL PRIMARY KEY,
  token_hash TEXT UNIQUE NOT NULL,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  user_agent TEXT,
  ip TEXT,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash);

CREATE TABLE IF NOT EXISTS pin_attempts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  ip TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TIMESTAMP,
  password_required_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS pin_attempts_user_id_idx ON pin_attempts(user_id);
CREATE INDEX IF NOT EXISTS pin_attempts_ip_idx ON pin_attempts(ip);

CREATE TABLE IF NOT EXISTS login_attempts (
  id SERIAL PRIMARY KEY,
  ip TEXT NOT NULL DEFAULT '',
  username TEXT,
  success BOOLEAN NOT NULL DEFAULT FALSE,
  identifier TEXT,
  attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TIMESTAMP,
  last_attempt_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS login_attempts_ip_idx ON login_attempts(ip);
CREATE INDEX IF NOT EXISTS login_attempts_identifier_idx ON login_attempts(identifier);

CREATE TABLE IF NOT EXISTS login_events (
  id SERIAL PRIMARY KEY,
  identifier TEXT NOT NULL,
  success BOOLEAN NOT NULL DEFAULT FALSE,
  reason TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS login_events_identifier_idx ON login_events(identifier);

CREATE TABLE IF NOT EXISTS scripts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  namespace TEXT NOT NULL DEFAULT 'http://tampermonkey.net/',
  version TEXT NOT NULL DEFAULT '1.0.0',
  description TEXT NOT NULL DEFAULT '',
  author TEXT NOT NULL DEFAULT '',
  matches TEXT[] NOT NULL DEFAULT '{}'::text[],
  grants TEXT[] NOT NULL DEFAULT '{}'::text[],
  run_at TEXT NOT NULL DEFAULT 'document-idle',
  update_url TEXT NOT NULL DEFAULT '',
  download_url TEXT NOT NULL DEFAULT '',
  code TEXT NOT NULL DEFAULT '',
  obfuscate_by_default BOOLEAN NOT NULL DEFAULT FALSE,
  code_hash TEXT NOT NULL DEFAULT '',
  source_url TEXT,
  last_check_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);
`;

async function initDb() {
  if (!process.env.DATABASE_URL) {
    // En Vercel las variables de entorno pueden no existir durante el build:
    // no rompemos el deploy, el esquema se crea en el primer request.
    console.warn("[init-db] DATABASE_URL no definida, se omite (se creara en runtime)");
    return;
  }

  const client = new Client({ connectionString: process.env.DATABASE_URL });

  try {
    await client.connect();
    console.log("[init-db] conectado");
    await client.query(SQL);
    console.log("[init-db] esquema creado/verificado");
  } catch (error) {
    console.error("[init-db] error:", error);
    process.exit(1);
  } finally {
    await client.end();
  }
}

initDb();
",
 "scripts/seed.mjs": "import "dotenv/config";
import { randomBytes, scrypt as scryptCallback } from "node:crypto";
import { promisify } from "node:util";
import pg from "pg";

const { Client } = pg;
const scrypt = promisify(scryptCallback);

const USERNAME = process.env.SEED_USERNAME ?? "admin";
const PASSWORD = process.env.SEED_PASSWORD ?? "tampervault";
const PIN = process.env.SEED_PIN ?? "123456";

async function hashSecret(secret) {
  const salt = randomBytes(16);
  const derived = await scrypt(secret, salt, 64, { N: 16384, r: 8, p: 1 });
  return `scrypt$16384$${salt.toString("hex")}$${derived.toString("hex")}`;
}

async function seed() {
  if (!process.env.DATABASE_URL) {
    console.error("DATABASE_URL no esta definida");
    process.exit(1);
  }
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();

    const existing = await client.query("SELECT id FROM users WHERE username = $1", [USERNAME]);
    if (existing.rowCount > 0) {
      console.log(`[seed] el usuario "${USERNAME}" ya existe, nada que hacer`);
      return;
    }

    const inserted = await client.query(
      "INSERT INTO users (username, password_hash, pin_hash) VALUES ($1, $2, $3) RETURNING id",
      [USERNAME, await hashSecret(PASSWORD), await hashSecret(PIN)],
    );
    const userId = inserted.rows[0].id;

    await client.query(
      `INSERT INTO scripts
        (user_id, name, version, description, author, matches, grants, run_at, code)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        userId,
        "Ejemplo: Hola Tampervault",
        "1.0.0",
        "Userscript de ejemplo",
        USERNAME,
        ["https://example.com/*"],
        ["GM_addStyle"],
        "document-idle",
        `// ==UserScript==\n// @name         Ejemplo: Hola Tampervault\n// @version      1.0.0\n// @match        https://example.com/*\n// @grant        GM_addStyle\n// ==/UserScript==\n\n(function () {\n  "use strict";\n  GM_addStyle("body { outline: 4px solid #10b981; }");\n})();\n`,
      ],
    );

    console.log(`[seed] usuario "${USERNAME}" creado con PIN ${PIN}`);
  } catch (error) {
    console.error("[seed] error:", error);
    process.exit(1);
  } finally {
    await client.end();
  }
}

seed();
