 "README.md": "# Tampervault\n\nBóveda privada (Next.js 16 + Drizzle + PostgreSQL) para almacenar, versionar,\nsincronizar y distribuir userscripts de Tampermonkey. El acceso se protege con\nPIN de 6 dígitos, bloqueo progresivo y recuperación por contraseña.\n\n## Estructura\n\n```\nsrc/\n├── app/\n│   ├── page.tsx                        # Login con PIN\n│   ├── dashboard/page.tsx              # Bóveda (protegida por sesión)\n│   └── api/\n│       ├── auth/pin/route.ts           # POST login con PIN / recuperación\n│       ├── auth/logout/route.ts        # POST cerrar sesión\n│       ├── auth/credentials/route.ts   # POST cambiar PIN / contraseña\n│       ├── health/route.ts             # GET healthcheck\n│       └── scripts/\n│           ├── route.ts                # GET lista · POST crear\n│           ├── [id]/route.ts           # GET · PATCH · DELETE\n│           ├── [id]/download/route.ts  # GET *.user.js (?obfuscate=1)\n│           └── check-updates/route.ts  # POST revisar todos · GET ?id=\n├── components/{pin-login,script-manager}.tsx\n├── db/{schema,index,bootstrap,seed}.ts\n└── lib/{auth,session,scripts,obfuscate}.ts\n```\n\n## Puesta en marcha\n\n1. `cp .env.example .env` y completa `DATABASE_URL` + `SESSION_SECRET`.\n2. `npm install`\n3. Crea el esquema: `npm run db:init` (o `npx drizzle-kit push`).\n4. Crea el usuario inicial: `npm run db:seed` → usuario `admin`, PIN `123456`,\n   contraseña `tampervault` (cámbialos desde el panel).\n5. `npm run dev` y abre `http://localhost:3000`.\n\n## Seguridad\n\n- PIN y contraseña se guardan con scrypt (`scrypt$N$salt$hash`).\n- Sesiones en base de datos: solo se guarda el SHA-256 del token; la cookie es\n  `httpOnly`, `sameSite=lax` y `secure` en producción.\n- 3 intentos de PIN por IP → bloqueo de 5 minutos + contraseña obligatoria\n  durante 10 minutos. Cada intento queda registrado en `login_events`.\n- La API de scripts siempre filtra por `user_id` de la sesión activa.\n- La descarga remota bloquea hosts internos y limita la respuesta a 2 MB.\n\n## Despliegue en Vercel\n\n1. Sube el repo a GitHub e impórtalo en Vercel.\n2. Añade las variables `DATABASE_URL` y `SESSION_SECRET`.\n3. `vercel.json` ejecuta `npm run build && node scripts/init-db.mjs`, así que el\n   esquema se crea automáticamente en cada despliegue.\n",
 "drizzle.config.ts": "import \"dotenv/config\";\nimport { defineConfig } from \"drizzle-kit\";\n\nexport default defineConfig({\n  dialect: \"postgresql\",\n  schema: \"./src/db/schema.ts\",\n  out: \"./drizzle\",\n  dbCredentials: {\n    url: process.env.DATABASE_URL ?? \"\",\n  },\n  strict: false,\n  verbose: true,\n});\n",
 "eslint.config.mjs": "// Configuracion plana (flat config) minima y sin dependencias extra.\n// Si quieres las reglas completas de Next instala eslint-config-next y usa\n// FlatCompat para extender \"next/core-web-vitals\".\nexport default [\n  {\n    ignores: [\"node_modules/**\", \".next/**\", \"dist/**\", \"coverage/**\"],\n  },\n  {\n    files: [\"**/*.{js,mjs,ts,tsx}\"],\n    rules: {\n      \"no-console\": \"off\",\n      eqeqeq: [\"warn\", \"smart\"],\n    },\n  },\n];\n",
 "next.config.ts": "import type { NextConfig } from \"next\";\n\nconst config: NextConfig = {\n  reactStrictMode: true,\n  poweredByHeader: false,\n};\n\nexport default config;\n",
 "package.json": "{\n  \"name\": \"tampervault\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\",\n    \"lint\": \"eslint .\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"db:init\": \"node scripts/init-db.mjs\",\n    \"db:seed\": \"node scripts/seed.mjs\"\n  },\n  \"dependencies\": {\n    \"dotenv\": \"17.3.1\",\n    \"drizzle-orm\": \"0.45.2\",\n    \"next\": \"16.2.6\",\n    \"pg\": \"8.20.0\",\n    \"react\": \"19.2.6\",\n    \"react-dom\": \"19.2.6\",\n    \"zod\": \"^4.6.5\"\n  },\n  \"devDependencies\": {\n    \"@tailwindcss/postcss\": \"4.1.17\",\n    \"@types/node\": \"22.19.15\",\n    \"@types/pg\": \"8.18.0\",\n    \"@types/react\": \"19.2.14\",\n    \"@types/react-dom\": \"19.2.3\",\n    \"drizzle-kit\": \"0.31.10\",\n    \"eslint\": \"9.39.4\",\n    \"eslint-config-next\": \"16.2.6\",\n    \"postcss\": \"8.5.8\",\n    \"tailwindcss\": \"4.1.17\",\n    \"typescript\": \"5.9.3\"\n  }\n}\n",
 "postcss.config.mjs": "const config = {\n  plugins: {\n    \"@tailwindcss/postcss\": {},\n  },\n};\n\nexport default config;\n",
 "scripts/init-db.mjs": "import \"dotenv/config\";\nimport pg from \"pg\";\n\nconst { Client } = pg;\n\nconst SQL = `\nCREATE TABLE IF NOT EXISTS users (\n  id SERIAL PRIMARY KEY,\n  username TEXT UNIQUE NOT NULL,\n  password_hash TEXT NOT NULL,\n  pin_hash TEXT,\n  totp_secret TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS sessions (\n  id SERIAL PRIMARY KEY,\n  token_hash TEXT UNIQUE NOT NULL,\n  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  user_agent TEXT,\n  ip TEXT,\n  expires_at TIMESTAMP NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash);\n\nCREATE TABLE IF NOT EXISTS pin_attempts (\n  id SERIAL PRIMARY KEY,\n  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  ip TEXT NOT NULL,\n  attempts INTEGER NOT NULL DEFAULT 0,\n  locked_until TIMESTAMP,\n  password_required_at TIMESTAMP,\n  created_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS pin_attempts_user_id_idx ON pin_attempts(user_id);\nCREATE INDEX IF NOT EXISTS pin_attempts_ip_idx ON pin_attempts(ip);\n\nCREATE TABLE IF NOT EXISTS login_attempts (\n  id SERIAL PRIMARY KEY,\n  ip TEXT NOT NULL DEFAULT '',\n  username TEXT,\n  success BOOLEAN NOT NULL DEFAULT FALSE,\n  identifier TEXT,\n  attempts INTEGER NOT NULL DEFAULT 0,\n  locked_until TIMESTAMP,\n  last_attempt_at TIMESTAMP,\n  created_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS login_attempts_ip_idx ON login_attempts(ip);\nCREATE INDEX IF NOT EXISTS login_attempts_identifier_idx ON login_attempts(identifier);\n\nCREATE TABLE IF NOT EXISTS login_events (\n  id SERIAL PRIMARY KEY,\n  identifier TEXT NOT NULL,\n  success BOOLEAN NOT NULL DEFAULT FALSE,\n  reason TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS login_events_identifier_idx ON login_events(identifier);\n\nCREATE TABLE IF NOT EXISTS scripts (\n  id SERIAL PRIMARY KEY,\n  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  namespace TEXT NOT NULL DEFAULT 'http://tampermonkey.net/',\n  version TEXT NOT NULL DEFAULT '1.0.0',\n  description TEXT NOT NULL DEFAULT '',\n  author TEXT NOT NULL DEFAULT '',\n  matches TEXT[] NOT NULL DEFAULT '{}'::text[],\n  grants TEXT[] NOT NULL DEFAULT '{}'::text[],\n  run_at TEXT NOT NULL DEFAULT 'document-idle',\n  update_url TEXT NOT NULL DEFAULT '',\n  download_url TEXT NOT NULL DEFAULT '',\n  code TEXT NOT NULL DEFAULT '',\n  obfuscate_by_default BOOLEAN NOT NULL DEFAULT FALSE,\n  code_hash TEXT NOT NULL DEFAULT '',\n  source_url TEXT,\n  last_check_at TIMESTAMP,\n  created_at TIMESTAMP NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMP NOT NULL DEFAULT NOW()\n);\n`;\n\nasync function initDb() {\n  if (!process.env.DATABASE_URL) {\n    console.error(\"DATABASE_URL no esta definida\");\n    process.exit(1);\n  }\n\n  const client = new Client({ connectionString: process.env.DATABASE_URL });\n\n  try {\n    await client.connect();\n    console.log(\"[init-db] conectado\");\n    await client.query(SQL);\n    console.log(\"[init-db] esquema creado/verificado\");\n  } catch (error) {\n    console.error(\"[init-db] error:\", error);\n    process.exit(1);\n  } finally {\n    await client.end();\n  }\n}\n\ninitDb();\n",
 "scripts/seed.mjs": "import \"dotenv/config\";\nimport { randomBytes, scrypt as scryptCallback } from \"node:crypto\";\nimport { promisify } from \"node:util\";\nimport pg from \"pg\";\n\nconst { Client } = pg;\nconst scrypt = promisify(scryptCallback);\n\nconst USERNAME = process.env.SEED_USERNAME ?? \"admin\";\nconst PASSWORD = process.env.SEED_PASSWORD ?? \"tampervault\";\nconst PIN = process.env.SEED_PIN ?? \"123456\";\n\nasync function hashSecret(secret) {\n  const salt = randomBytes(16);\n  const derived = await scrypt(secret, salt, 64, { N: 16384, r: 8, p: 1 });\n  return `scrypt$16384$${salt.toString(\"hex\")}$${derived.toString(\"hex\")}`;\n}\n\nasync function seed() {\n  if (!process.env.DATABASE_URL) {\n    console.error(\"DATABASE_URL no esta definida\");\n    process.exit(1);\n  }\n\n  const client = new Client({ connectionString: process.env.DATABASE_URL });\n  try {\n    await client.connect();\n\n    const existing = await client.query(\"SELECT id FROM users WHERE username = $1\", [USERNAME]);\n    if (existing.rowCount > 0) {\n      console.log(`[seed] el usuario \"${USERNAME}\" ya existe, nada que hacer`);\n      return;\n    }\n\n    const inserted = await client.query(\n      \"INSERT INTO users (username, password_hash, pin_hash) VALUES ($1, $2, $3) RETURNING id\",\n      [USERNAME, await hashSecret(PASSWORD), await hashSecret(PIN)],\n    );\n    const userId = inserted.rows[0].id;\n\n    await client.query(\n      `INSERT INTO scripts\n        (user_id, name, version, description, author, matches, grants, run_at, code)\n       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,\n      [\n        userId,\n        \"Ejemplo: Hola Tampervault\",\n        \"1.0.0\",\n        \"Userscript de ejemplo\",\n        USERNAME,\n        [\"https://example.com/*\"],\n        [\"GM_addStyle\"],\n        \"document-idle\",\n        `// ==UserScript==\\n// @name         Ejemplo: Hola Tampervault\\n// @version      1.0.0\\n// @match        https://example.com/*\\n// @grant        GM_addStyle\\n// ==/UserScript==\\n\\n(function () {\\n  \"use strict\";\\n  GM_addStyle(\"body { outline: 4px solid #10b981; }\");\\n})();\\n`,\n      ],\n    );\n\n    console.log(`[seed] usuario \"${USERNAME}\" creado con PIN ${PIN}`);\n  } catch (error) {\n    console.error(\"[seed] error:\", error);\n    process.exit(1);\n  } finally {\n    await client.end();\n  }\n}\n\nseed();\n",
 "src/app/api/auth/credentials/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { eq } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { users } from \"@/db/schema\";\nimport { hashSecret, isValidPin, verifySecret } from \"@/lib/auth\";\nimport { getCurrentUser } from \"@/lib/session\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function GET() {\n  const user = await getCurrentUser();\n  if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n  return NextResponse.json({\n    username: user.username,\n    hasPin: Boolean(user.pinHash),\n    createdAt: user.createdAt,\n  });\n}\n\n/** POST { currentPassword, newPassword?, newPin? } */\nexport async function POST(req: NextRequest) {\n  try {\n    const user = await getCurrentUser();\n    if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;\n    const currentPassword = typeof body.currentPassword === \"string\" ? body.currentPassword : \"\";\n    if (!currentPassword) {\n      return NextResponse.json({ error: \"Confirma tu contrasena actual\" }, { status: 400 });\n    }\n    if (!(await verifySecret(currentPassword, user.passwordHash))) {\n      return NextResponse.json({ error: \"Contrasena actual incorrecta\" }, { status: 401 });\n    }\n\n    const patch: { passwordHash?: string; pinHash?: string } = {};\n\n    if (typeof body.newPassword === \"string\" && body.newPassword.length > 0) {\n      if (body.newPassword.length < 8) {\n        return NextResponse.json(\n          { error: \"La nueva contrasena debe tener 8+ caracteres\" },\n          { status: 400 },\n        );\n      }\n      patch.passwordHash = await hashSecret(body.newPassword);\n    }\n\n    if (typeof body.newPin === \"string\" && body.newPin.length > 0) {\n      if (!isValidPin(body.newPin)) {\n        return NextResponse.json({ error: \"El PIN debe tener 6 digitos\" }, { status: 400 });\n      }\n      patch.pinHash = await hashSecret(body.newPin);\n    }\n\n    if (Object.keys(patch).length === 0) {\n      return NextResponse.json({ error: \"Nada que actualizar\" }, { status: 400 });\n    }\n\n    await db.update(users).set(patch).where(eq(users.id, user.id));\n    return NextResponse.json({ success: true, updated: Object.keys(patch) });\n  } catch (error) {\n    console.error(\"[auth/credentials]\", error);\n    return NextResponse.json({ error: \"Error actualizando credenciales\" }, { status: 500 });\n  }\n}\n",
 "src/app/api/auth/logout/route.ts": "import { NextResponse } from \"next/server\";\nimport { clearSessionCookie, destroyCurrentSession } from \"@/lib/session\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function POST() {\n  try {\n    await destroyCurrentSession();\n  } catch (error) {\n    console.error(\"[auth/logout]\", error);\n  }\n\n  const response = NextResponse.json({ success: true });\n  clearSessionCookie(response);\n  return response;\n}\n",
 "src/app/api/auth/pin/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { and, eq } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { loginEvents, pinAttempts, users } from \"@/db/schema\";\nimport { isValidPin, normalizeIp, verifySecret } from \"@/lib/auth\";\nimport { createSession, setSessionCookie } from \"@/lib/session\";\nimport { ensureSeed } from \"@/db/seed\";\n\nexport const dynamic = \"force-dynamic\";\n\nconst MAX_ATTEMPTS = 3;\nconst LOCK_MINUTES = 5;\nconst PASSWORD_WINDOW_MINUTES = 10;\n\nexport async function POST(req: NextRequest) {\n  try {\n    await ensureSeed();\n\n    const body = (await req.json().catch(() => ({}))) as {\n      pin?: unknown;\n      requirePassword?: unknown;\n      password?: unknown;\n    };\n\n    const pin = body.pin;\n    const requirePassword = body.requirePassword === true;\n    const password = typeof body.password === \"string\" ? body.password : \"\";\n    const ip = normalizeIp(req.headers.get(\"x-forwarded-for\"));\n    const userAgent = req.headers.get(\"user-agent\") ?? \"unknown\";\n\n    if (!isValidPin(pin)) {\n      return NextResponse.json(\n        { error: \"El PIN debe tener exactamente 6 digitos\" },\n        { status: 400 },\n      );\n    }\n\n    const user = (await db.select().from(users).limit(1))[0];\n    if (!user || !user.pinHash) {\n      return NextResponse.json({ error: \"No hay PIN configurado\" }, { status: 400 });\n    }\n\n    const blockRecord = (\n      await db\n        .select()\n        .from(pinAttempts)\n        .where(and(eq(pinAttempts.userId, user.id), eq(pinAttempts.ip, ip)))\n        .limit(1)\n    )[0];\n\n    const now = new Date();\n\n    if (blockRecord?.lockedUntil && blockRecord.lockedUntil > now) {\n      const unlockTime = Math.ceil(\n        (blockRecord.lockedUntil.getTime() - now.getTime()) / 1000,\n      );\n      await logEvent(user.username, false, \"locked\");\n      return NextResponse.json(\n        {\n          error: `Demasiados intentos. Bloqueado ${unlockTime}s`,\n          requiresPassword: true,\n          unlockTime,\n        },\n        { status: 429 },\n      );\n    }\n\n    if (blockRecord?.passwordRequiredAt && blockRecord.passwordRequiredAt > now) {\n      if (!requirePassword) {\n        return NextResponse.json(\n          { error: \"Se requiere contrasena despues del bloqueo\", requiresPassword: true },\n          { status: 429 },\n        );\n      }\n      if (!password) {\n        return NextResponse.json({ error: \"Contrasena requerida\" }, { status: 400 });\n      }\n\n      const passwordOk = await verifySecret(password, user.passwordHash);\n      if (!passwordOk) {\n        await db\n          .update(pinAttempts)\n          .set({ attempts: (blockRecord.attempts ?? 0) + 1 })\n          .where(eq(pinAttempts.id, blockRecord.id));\n        await logEvent(user.username, false, \"bad-password-recovery\");\n        return NextResponse.json({ error: \"Contrasena incorrecta\" }, { status: 401 });\n      }\n\n      await resetBlock(blockRecord.id);\n      await logEvent(user.username, true, \"password-recovery\");\n      return startSession(user.id, ip, userAgent, \"Acceso concedido con contrasena\");\n    }\n\n    const pinOk = await verifySecret(pin, user.pinHash);\n\n    if (!pinOk) {\n      const attempts = (blockRecord?.attempts ?? 0) + 1;\n      const shouldLock = attempts >= MAX_ATTEMPTS;\n\n      if (blockRecord) {\n        await db\n          .update(pinAttempts)\n          .set({\n            attempts,\n            lockedUntil: shouldLock ? new Date(now.getTime() + LOCK_MINUTES * 60_000) : null,\n            passwordRequiredAt: shouldLock\n              ? new Date(now.getTime() + PASSWORD_WINDOW_MINUTES * 60_000)\n              : null,\n          })\n          .where(eq(pinAttempts.id, blockRecord.id));\n      } else {\n        await db.insert(pinAttempts).values({\n          userId: user.id,\n          ip,\n          attempts,\n          lockedUntil: shouldLock ? new Date(now.getTime() + LOCK_MINUTES * 60_000) : null,\n          passwordRequiredAt: shouldLock\n            ? new Date(now.getTime() + PASSWORD_WINDOW_MINUTES * 60_000)\n            : null,\n        });\n      }\n\n      await logEvent(user.username, false, shouldLock ? \"locked-out\" : \"bad-pin\");\n\n      if (shouldLock) {\n        return NextResponse.json(\n          {\n            error: `PIN incorrecto. Bloqueado por ${LOCK_MINUTES} minutos.`,\n            requiresPassword: true,\n            unlockTime: LOCK_MINUTES * 60,\n          },\n          { status: 429 },\n        );\n      }\n\n      const remaining = Math.max(0, MAX_ATTEMPTS - attempts);\n      return NextResponse.json(\n        {\n          error: `PIN incorrecto. Intentos restantes: ${remaining}`,\n          attemptsRemaining: remaining,\n        },\n        { status: 401 },\n      );\n    }\n\n    if (blockRecord) await resetBlock(blockRecord.id);\n    await logEvent(user.username, true, \"pin\");\n    return startSession(user.id, ip, userAgent, \"PIN valido\");\n  } catch (error) {\n    console.error(\"[auth/pin]\", error);\n    return NextResponse.json({ error: \"Error en autenticacion\" }, { status: 500 });\n  }\n}\n\nasync function startSession(\n  userId: number,\n  ip: string,\n  userAgent: string,\n  message: string,\n): Promise<NextResponse> {\n  const token = await createSession(userId, { ip, userAgent });\n  const response = NextResponse.json({ success: true, message });\n  setSessionCookie(response, token);\n  return response;\n}\n\nasync function resetBlock(id: number): Promise<void> {\n  await db\n    .update(pinAttempts)\n    .set({ attempts: 0, lockedUntil: null, passwordRequiredAt: null })\n    .where(eq(pinAttempts.id, id));\n}\n\nasync function logEvent(\n  identifier: string,\n  success: boolean,\n  reason: string,\n): Promise<void> {\n  try {\n    await db.insert(loginEvents).values({ identifier, success, reason });\n  } catch (error) {\n    console.error(\"[auth/pin] logEvent\", error);\n  }\n}\n",
 "src/app/api/health/route.ts": "import { db } from \"@/db\";\nimport { sql } from \"drizzle-orm\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function GET() {\n  try {\n    await db.execute(sql`select 1`);\n    return Response.json({ ok: true, service: \"tampervault\" });\n  } catch {\n    return Response.json({ ok: false }, { status: 500 });\n  }\n}\n",
 "src/app/api/scripts/[id]/download/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { and, eq } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { scripts } from \"@/db/schema\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { renderUserScript } from \"@/lib/scripts\";\n\nexport const dynamic = \"force-dynamic\";\n\nfunction slugify(value: string): string {\n  return (\n    value\n      .toLowerCase()\n      .normalize(\"NFD\")\n      .replace(/[\\u0300-\\u036f]/g, \"\")\n      .replace(/[^a-z0-9]+/g, \"-\")\n      .replace(/^-+|-+$/g, \"\")\n      .slice(0, 60) || \"script\"\n  );\n}\n\nexport async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {\n  const user = await getCurrentUser();\n  if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n  const { id } = await ctx.params;\n  const scriptId = Number.parseInt(id, 10);\n  if (!Number.isFinite(scriptId)) {\n    return NextResponse.json({ error: \"ID invalido\" }, { status: 400 });\n  }\n\n  const script = (\n    await db\n      .select()\n      .from(scripts)\n      .where(and(eq(scripts.id, scriptId), eq(scripts.userId, user.id)))\n      .limit(1)\n  )[0];\n\n  if (!script) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n\n  const obfuscated =\n    req.nextUrl.searchParams.get(\"obfuscate\") === \"1\" || script.obfuscateByDefault;\n  const installUrl = `${req.nextUrl.origin}/api/scripts/${script.id}/download`;\n\n  const output = renderUserScript(\n    {\n      ...script,\n      updateUrl: script.updateUrl || installUrl,\n      downloadUrl: script.downloadUrl || installUrl,\n    },\n    obfuscated,\n  );\n\n  return new NextResponse(output, {\n    status: 200,\n    headers: {\n      \"content-type\": \"text/javascript; charset=utf-8\",\n      \"content-disposition\": `attachment; filename=\"${slugify(script.name)}-${script.version}.user.js\"`,\n      \"cache-control\": \"no-store\",\n    },\n  });\n}\n",
 "src/app/api/scripts/[id]/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { and, eq } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { scripts } from \"@/db/schema\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { fetchRemoteCode, normalizeScriptInput, scriptHash } from \"@/lib/scripts\";\n\nexport const dynamic = \"force-dynamic\";\n\ntype Ctx = { params: Promise<{ id: string }> };\n\nasync function load(userId: number, rawId: string) {\n  const id = Number.parseInt(rawId, 10);\n  if (!Number.isFinite(id)) return null;\n  const row = (\n    await db\n      .select()\n      .from(scripts)\n      .where(and(eq(scripts.id, id), eq(scripts.userId, userId)))\n      .limit(1)\n  )[0];\n  return row ?? null;\n}\n\nexport async function GET(_req: NextRequest, ctx: Ctx) {\n  const user = await getCurrentUser();\n  if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n  const { id } = await ctx.params;\n  const script = await load(user.id, id);\n  if (!script) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n  return NextResponse.json({ script });\n}\n\nexport async function PATCH(req: NextRequest, ctx: Ctx) {\n  try {\n    const user = await getCurrentUser();\n    if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n    const { id } = await ctx.params;\n    const script = await load(user.id, id);\n    if (!script) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n\n    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;\n    const input = normalizeScriptInput({ ...script, ...body });\n\n    let code = input.code;\n    if (body.refetchFromSource === true && input.sourceUrl) {\n      const remote = await fetchRemoteCode(input.sourceUrl);\n      if (!remote.ok) {\n        return NextResponse.json({ error: remote.error }, { status: 400 });\n      }\n      code = remote.code;\n    }\n\n    const updated = await db\n      .update(scripts)\n      .set({ ...input, code, codeHash: scriptHash(code), updatedAt: new Date() })\n      .where(eq(scripts.id, script.id))\n      .returning();\n\n    return NextResponse.json({ script: updated[0] });\n  } catch (error) {\n    console.error(\"[scripts PATCH]\", error);\n    return NextResponse.json({ error: \"No se pudo actualizar\" }, { status: 500 });\n  }\n}\n\nexport async function DELETE(_req: NextRequest, ctx: Ctx) {\n  const user = await getCurrentUser();\n  if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n  const { id } = await ctx.params;\n  const script = await load(user.id, id);\n  if (!script) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n\n  await db.delete(scripts).where(eq(scripts.id, script.id));\n  return NextResponse.json({ success: true });\n}\n",
 "src/app/api/scripts/check-updates/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { and, eq, inArray } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { scripts } from \"@/db/schema\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { fetchRemoteCode, scriptHash } from \"@/lib/scripts\";\n\nexport const dynamic = \"force-dynamic\";\n\ntype Result = {\n  id: number;\n  name: string;\n  status: \"updated\" | \"unchanged\" | \"error\" | \"skipped\";\n  detail?: string;\n};\n\n/** POST { scriptIds?: number[] } — revisa todos (o los indicados) y actualiza el codigo. */\nexport async function POST(req: NextRequest) {\n  try {\n    const user = await getCurrentUser();\n    if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n    const body = (await req.json().catch(() => ({}))) as { scriptIds?: unknown };\n    const requested = Array.isArray(body.scriptIds)\n      ? body.scriptIds.map(Number).filter(Number.isFinite)\n      : [];\n\n    const rows = requested.length\n      ? await db\n          .select()\n          .from(scripts)\n          .where(and(eq(scripts.userId, user.id), inArray(scripts.id, requested)))\n      : await db.select().from(scripts).where(eq(scripts.userId, user.id));\n\n    const results: Result[] = [];\n\n    for (const script of rows) {\n      if (!script.sourceUrl) {\n        results.push({ id: script.id, name: script.name, status: \"skipped\", detail: \"Sin URL de origen\" });\n        continue;\n      }\n\n      const remote = await fetchRemoteCode(script.sourceUrl);\n      if (!remote.ok) {\n        results.push({ id: script.id, name: script.name, status: \"error\", detail: remote.error });\n        continue;\n      }\n\n      const newHash = scriptHash(remote.code);\n      if (newHash === script.codeHash) {\n        await db.update(scripts).set({ lastCheckAt: new Date() }).where(eq(scripts.id, script.id));\n        results.push({ id: script.id, name: script.name, status: \"unchanged\" });\n        continue;\n      }\n\n      await db\n        .update(scripts)\n        .set({ code: remote.code, codeHash: newHash, lastCheckAt: new Date(), updatedAt: new Date() })\n        .where(eq(scripts.id, script.id));\n\n      results.push({ id: script.id, name: script.name, status: \"updated\" });\n    }\n\n    return NextResponse.json({\n      checked: rows.length,\n      updates: results.filter((r) => r.status === \"updated\").length,\n      results,\n      timestamp: new Date().toISOString(),\n    });\n  } catch (error) {\n    console.error(\"[check-updates POST]\", error);\n    return NextResponse.json({ error: \"Error verificando actualizaciones\" }, { status: 500 });\n  }\n}\n\n/** GET /api/scripts/check-updates?id=1 — revisa un script concreto. */\nexport async function GET(req: NextRequest) {\n  try {\n    const user = await getCurrentUser();\n    if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n    const scriptId = Number.parseInt(req.nextUrl.searchParams.get(\"id\") ?? \"\", 10);\n    if (!Number.isFinite(scriptId)) {\n      return NextResponse.json({ error: \"ID de script requerido\" }, { status: 400 });\n    }\n\n    const script = (\n      await db\n        .select()\n        .from(scripts)\n        .where(and(eq(scripts.id, scriptId), eq(scripts.userId, user.id)))\n        .limit(1)\n    )[0];\n\n    if (!script) return NextResponse.json({ error: \"No encontrado\" }, { status: 404 });\n    if (!script.sourceUrl) {\n      return NextResponse.json({ error: \"El script no tiene URL de origen\" }, { status: 400 });\n    }\n\n    const remote = await fetchRemoteCode(script.sourceUrl);\n    if (!remote.ok) return NextResponse.json({ error: remote.error }, { status: 502 });\n\n    const newHash = scriptHash(remote.code);\n    const hasUpdate = newHash !== script.codeHash;\n\n    await db\n      .update(scripts)\n      .set(\n        hasUpdate\n          ? { code: remote.code, codeHash: newHash, lastCheckAt: new Date(), updatedAt: new Date() }\n          : { lastCheckAt: new Date() },\n      )\n      .where(eq(scripts.id, script.id));\n\n    return NextResponse.json({\n      id: script.id,\n      name: script.name,\n      hasUpdate,\n      oldHash: script.codeHash,\n      newHash,\n      newCodeSize: remote.code.length,\n      lastCheck: new Date().toISOString(),\n    });\n  } catch (error) {\n    console.error(\"[check-updates GET]\", error);\n    return NextResponse.json({ error: \"Error en la solicitud\" }, { status: 500 });\n  }\n}\n",
 "src/app/api/scripts/route.ts": "import { NextResponse, type NextRequest } from \"next/server\";\nimport { desc, eq } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { scripts } from \"@/db/schema\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { fetchRemoteCode, normalizeScriptInput, publicScript, scriptHash } from \"@/lib/scripts\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport async function GET() {\n  const user = await getCurrentUser();\n  if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n  const rows = await db\n    .select()\n    .from(scripts)\n    .where(eq(scripts.userId, user.id))\n    .orderBy(desc(scripts.updatedAt));\n\n  return NextResponse.json({ scripts: rows.map(publicScript) });\n}\n\nexport async function POST(req: NextRequest) {\n  try {\n    const user = await getCurrentUser();\n    if (!user) return NextResponse.json({ error: \"No autenticado\" }, { status: 401 });\n\n    const body = await req.json().catch(() => ({}));\n    const input = normalizeScriptInput(body as Record<string, unknown>);\n\n    if (!input.name.trim()) {\n      return NextResponse.json({ error: \"El nombre es obligatorio\" }, { status: 400 });\n    }\n\n    let code = input.code;\n    if (!code.trim() && input.sourceUrl) {\n      const remote = await fetchRemoteCode(input.sourceUrl);\n      if (!remote.ok) {\n        return NextResponse.json(\n          { error: `No se pudo importar: ${remote.error}` },\n          { status: 400 },\n        );\n      }\n      code = remote.code;\n    }\n\n    const inserted = await db\n      .insert(scripts)\n      .values({ ...input, userId: user.id, code, codeHash: scriptHash(code) })\n      .returning();\n\n    return NextResponse.json({ script: publicScript(inserted[0]) }, { status: 201 });\n  } catch (error) {\n    console.error(\"[scripts POST]\", error);\n    return NextResponse.json({ error: \"No se pudo crear el script\" }, { status: 500 });\n  }\n}\n",
 "src/app/dashboard/page.tsx": "import { redirect } from \"next/navigation\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { ScriptManager } from \"@/components/script-manager\";\nimport { db } from \"@/db\";\nimport { scripts } from \"@/db/schema\";\nimport { desc, eq } from \"drizzle-orm\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function DashboardPage() {\n  const user = await getCurrentUser();\n  if (!user) redirect(\"/\");\n\n  const rows = await db\n    .select()\n    .from(scripts)\n    .where(eq(scripts.userId, user.id))\n    .orderBy(desc(scripts.updatedAt));\n\n  return (\n    <main className=\"mx-auto max-w-6xl px-6 py-10\">\n      <ScriptManager\n        username={user.username}\n        initialScripts={rows.map((row) => ({\n          ...row,\n          createdAt: row.createdAt.toISOString(),\n          updatedAt: row.updatedAt.toISOString(),\n          lastCheckAt: row.lastCheckAt ? row.lastCheckAt.toISOString() : null,\n        }))}\n      />\n    </main>\n  );\n}\n",
 "src/app/globals.css": "@import \"tailwindcss\";\n\n:root {\n  color-scheme: dark;\n}\n\ntextarea,\ninput,\nselect {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n",
 "src/app/layout.tsx": "import type { Metadata } from \"next\";\nimport type { ReactNode } from \"react\";\nimport \"./globals.css\";\n\nexport const metadata: Metadata = {\n  title: \"Tampervault — boveda de userscripts\",\n  description:\n    \"Boveda privada con PIN para almacenar, versionar y distribuir userscripts de Tampermonkey.\",\n};\n\nexport default function RootLayout({ children }: { children: ReactNode }) {\n  return (\n    <html lang=\"es\">\n      <body className=\"bg-slate-950 text-slate-100 antialiased\">{children}</body>\n    </html>\n  );\n}\n",
 "src/app/page.tsx": "import { redirect } from \"next/navigation\";\nimport { PinLogin } from \"@/components/pin-login\";\nimport { getCurrentUser } from \"@/lib/session\";\nimport { DEFAULT_PIN, DEFAULT_PASSWORD, ensureSeed } from \"@/db/seed\";\n\nexport const dynamic = \"force-dynamic\";\n\nexport default async function LoginPage() {\n  await ensureSeed();\n  const user = await getCurrentUser();\n  if (user) redirect(\"/dashboard\");\n\n  return (\n    <main className=\"flex min-h-screen items-center justify-center bg-gradient-to-br from-slate-950 via-slate-900 to-slate-800 p-6\">\n      <div className=\"w-full max-w-md space-y-4\">\n        <PinLogin />\n        <div className=\"rounded-xl border border-slate-800 bg-slate-900/60 p-4 text-xs text-slate-400\">\n          <p className=\"font-semibold text-slate-300\">Primer acceso</p>\n          <p className=\"mt-1\">\n            PIN <code className=\"text-emerald-400\">{DEFAULT_PIN}</code> · contrasena de\n            recuperacion <code className=\"text-emerald-400\">{DEFAULT_PASSWORD}</code>\n          </p>\n          <p className=\"mt-1\">Cambialos desde el panel, en Credenciales.</p>\n        </div>\n      </div>\n    </main>\n  );\n}\n",
 "src/components/pin-login.tsx": "\"use client\";\n\nimport { useEffect, useState, type FormEvent } from \"react\";\n\ntype Mode = \"pin\" | \"locked\" | \"password\" | \"success\";\n\nexport function PinLogin() {\n  const [pin, setPin] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [mode, setMode] = useState<Mode>(\"pin\");\n  const [error, setError] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [lockTimeLeft, setLockTimeLeft] = useState(0);\n\n  useEffect(() => {\n    if (lockTimeLeft <= 0) return;\n    const timer = setInterval(() => setLockTimeLeft((prev) => Math.max(0, prev - 1)), 1000);\n    return () => clearInterval(timer);\n  }, [lockTimeLeft]);\n\n  async function submit(payload: Record<string, unknown>) {\n    setError(\"\");\n    setLoading(true);\n    try {\n      const res = await fetch(\"/api/auth/pin\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(payload),\n      });\n      const data = (await res.json().catch(() => ({}))) as {\n        error?: string;\n        requiresPassword?: boolean;\n        unlockTime?: number;\n      };\n\n      if (res.ok) {\n        setMode(\"success\");\n        setTimeout(() => window.location.assign(\"/dashboard\"), 700);\n        return;\n      }\n\n      if (data.requiresPassword) {\n        setMode(\"password\");\n        if (data.unlockTime && data.unlockTime > 0) setLockTimeLeft(data.unlockTime);\n      }\n      setError(data.error ?? \"No se pudo validar el acceso\");\n    } catch {\n      setError(\"Error de conexion con el servidor\");\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  function onPinSubmit(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    void submit({ pin, requirePassword: false });\n  }\n\n  function onPasswordSubmit(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    void submit({ pin, requirePassword: true, password });\n  }\n\n  if (mode === \"success\") {\n    return (\n      <div className=\"w-full rounded-2xl border border-emerald-800 bg-emerald-950/70 p-8 text-center\">\n        <h1 className=\"text-2xl font-bold text-emerald-100\">Acceso valido</h1>\n        <p className=\"mt-2 text-emerald-300\">Redirigiendo al boveda...</p>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"w-full rounded-2xl border border-slate-800 bg-slate-900/80 p-8 shadow-2xl backdrop-blur\">\n      <h1 className=\"text-3xl font-bold text-white\">Tampervault</h1>\n      <p className=\"mt-1 text-sm text-slate-400\">\n        {mode === \"password\"\n          ? \"Bloqueo activo: ingresa tu contrasena para continuar\"\n          : \"Boveda privada de userscripts\"}\n      </p>\n\n      {mode === \"pin\" ? (\n        <form onSubmit={onPinSubmit} className=\"mt-8 space-y-4\">\n          <label className=\"block text-sm font-medium text-slate-300\" htmlFor=\"pin\">\n            PIN de acceso (6 digitos)\n          </label>\n          <input\n            id=\"pin\"\n            type=\"password\"\n            inputMode=\"numeric\"\n            autoComplete=\"off\"\n            placeholder=\"000000\"\n            value={pin}\n            onChange={(e) => setPin(e.target.value.replace(/\\D/g, \"\").slice(0, 6))}\n            maxLength={6}\n            required\n            disabled={loading}\n            className=\"w-full rounded-lg border border-slate-700 bg-slate-800 px-4 py-3 text-center text-2xl tracking-[0.5em] text-white focus:border-emerald-500 focus:outline-none disabled:opacity-50\"\n          />\n\n          {error && (\n            <p className=\"rounded-lg border border-red-800 bg-red-950/60 p-3 text-sm text-red-200\">\n              {error}\n            </p>\n          )}\n\n          <button\n            type=\"submit\"\n            disabled={loading || pin.length !== 6}\n            className=\"w-full rounded-lg bg-emerald-600 py-2.5 font-semibold text-white transition hover:bg-emerald-500 disabled:cursor-not-allowed disabled:opacity-50\"\n          >\n            {loading ? \"Verificando...\" : \"Ingresar\"}\n          </button>\n        </form>\n      ) : (\n        <form onSubmit={onPasswordSubmit} className=\"mt-8 space-y-4\">\n          {lockTimeLeft > 0 && (\n            <p className=\"rounded-lg border border-amber-800 bg-amber-950/50 p-3 text-sm text-amber-200\">\n              Bloqueado. Espera {lockTimeLeft}s o usa tu contrasena.\n            </p>\n          )}\n\n          <input\n            type=\"password\"\n            autoComplete=\"current-password\"\n            placeholder=\"Contrasena de recuperacion\"\n            value={password}\n            onChange={(e) => setPassword(e.target.value)}\n            maxLength={80}\n            required\n            disabled={loading}\n            className=\"w-full rounded-lg border border-slate-700 bg-slate-800 px-4 py-2.5 text-white focus:border-emerald-500 focus:outline-none disabled:opacity-50\"\n          />\n\n          {error && <p className=\"text-sm text-red-400\">{error}</p>}\n\n          <button\n            type=\"submit\"\n            disabled={loading}\n            className=\"w-full rounded-lg bg-emerald-600 py-2.5 font-semibold text-white transition hover:bg-emerald-500 disabled:opacity-50\"\n          >\n            {loading ? \"Verificando...\" : \"Desbloquear\"}\n          </button>\n\n          <button\n            type=\"button\"\n            onClick={() => {\n              setMode(\"pin\");\n              setError(\"\");\n              setPassword(\"\");\n            }}\n            className=\"w-full text-xs text-slate-400 underline hover:text-slate-200\"\n          >\n            Volver al PIN\n          </button>\n        </form>\n      )}\n\n      <p className=\"mt-8 border-t border-slate-800 pt-4 text-xs leading-relaxed text-slate-500\">\n        <strong className=\"text-slate-400\">Politica de seguridad:</strong> 3 intentos de\n        PIN, bloqueo de 5 minutos y despues contrasena obligatoria durante 10 minutos.\n      </p>\n    </div>\n  );\n}\n",
 "src/components/script-manager.tsx": "\"use client\";\n\nimport { useMemo, useState } from \"react\";\n\nexport type ScriptRow = {\n  id: number;\n  name: string;\n  namespace: string;\n  version: string;\n  description: string;\n  author: string;\n  matches: string[];\n  grants: string[];\n  runAt: string;\n  updateUrl: string;\n  downloadUrl: string;\n  code: string;\n  codeHash: string;\n  sourceUrl: string | null;\n  obfuscateByDefault: boolean;\n  lastCheckAt: string | null;\n  createdAt: string;\n  updatedAt: string;\n};\n\nconst emptyForm = {\n  name: \"\",\n  version: \"1.0.0\",\n  description: \"\",\n  author: \"\",\n  matches: \"\",\n  grants: \"GM_addStyle\",\n  runAt: \"document-idle\",\n  sourceUrl: \"\",\n  code: `// ==UserScript==\\n// ==/UserScript==\\n\\n(function () {\\n  \"use strict\";\\n})();\\n`,\n  obfuscateByDefault: false,\n};\n\nexport function ScriptManager({\n  username,\n  initialScripts,\n}: {\n  username: string;\n  initialScripts: ScriptRow[];\n}) {\n  const [items, setItems] = useState<ScriptRow[]>(initialScripts);\n  const [form, setForm] = useState({ ...emptyForm });\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [message, setMessage] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [pinForm, setPinForm] = useState({ currentPassword: \"\", newPin: \"\", newPassword: \"\" });\n\n  const stats = useMemo(\n    () => ({\n      total: items.length,\n      withSource: items.filter((s) => s.sourceUrl).length,\n      obfuscated: items.filter((s) => s.obfuscateByDefault).length,\n      bytes: items.reduce((acc, s) => acc + s.code.length, 0),\n    }),\n    [items],\n  );\n\n  async function call(url: string, init?: RequestInit) {\n    setBusy(true);\n    setMessage(\"\");\n    try {\n      const res = await fetch(url, {\n        ...init,\n        headers: init?.body ? { \"Content-Type\": \"application/json\" } : undefined,\n      });\n      const data = await res.json().catch(() => ({}));\n      if (!res.ok) throw new Error((data as { error?: string }).error ?? \"Error\");\n      return data as Record<string, unknown>;\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function reload() {\n    const data = await call(\"/api/scripts\");\n    setItems((data.scripts as ScriptRow[]) ?? []);\n  }\n\n  async function save() {\n    try {\n      if (editingId) {\n        await call(`/api/scripts/${editingId}`, { method: \"PATCH\", body: JSON.stringify(form) });\n        setMessage(\"Script actualizado\");\n      } else {\n        await call(\"/api/scripts\", { method: \"POST\", body: JSON.stringify(form) });\n        setMessage(\"Script creado\");\n      }\n      setForm({ ...emptyForm });\n      setEditingId(null);\n      await reload();\n    } catch (error) {\n      setMessage((error as Error).message);\n    }\n  }\n\n  async function remove(id: number) {\n    if (!confirm(\"Eliminar este script de la boveda?\")) return;\n    await call(`/api/scripts/${id}`, { method: \"DELETE\" });\n    await reload();\n    setMessage(\"Script eliminado\");\n  }\n\n  async function edit(id: number) {\n    const data = await call(`/api/scripts/${id}`);\n    const script = data.script as ScriptRow;\n    setEditingId(id);\n    setForm({\n      name: script.name,\n      version: script.version,\n      description: script.description,\n      author: script.author,\n      matches: script.matches.join(\"\\n\"),\n      grants: script.grants.join(\"\\n\"),\n      runAt: script.runAt,\n      sourceUrl: script.sourceUrl ?? \"\",\n      code: script.code,\n      obfuscateByDefault: script.obfuscateByDefault,\n    });\n  }\n\n  async function checkAll() {\n    const data = await call(\"/api/scripts/check-updates\", { method: \"POST\", body: \"{}\" });\n    const updates = Number(data.updates ?? 0);\n    setMessage(\n      `${data.checked} revisados · ${updates} actualizados · ${\n        (data.results as { status: string }[]).filter((r) => r.status === \"error\").length\n      } errores`,\n    );\n    await reload();\n  }\n\n  async function logout() {\n    await fetch(\"/api/auth/logout\", { method: \"POST\" });\n    window.location.assign(\"/\");\n  }\n\n  async function saveCredentials() {\n    try {\n      await call(\"/api/auth/credentials\", { method: \"POST\", body: JSON.stringify(pinForm) });\n      setMessage(\"Credenciales actualizadas\");\n      setPinForm({ currentPassword: \"\", newPin: \"\", newPassword: \"\" });\n    } catch (error) {\n      setMessage((error as Error).message);\n    }\n  }\n\n  const input =\n    \"w-full rounded-lg border border-slate-700 bg-slate-900 px-3 py-2 text-sm text-slate-100 focus:border-emerald-500 focus:outline-none\";\n\n  return (\n    <div className=\"space-y-8\">\n      <header className=\"flex flex-wrap items-center justify-between gap-4\">\n        <div>\n          <h1 className=\"text-2xl font-bold\">Boveda de {username}</h1>\n          <p className=\"text-sm text-slate-400\">\n            {stats.total} scripts · {stats.withSource} con origen remoto · {stats.obfuscated}{\" \"}\n            ofuscados · {(stats.bytes / 1024).toFixed(1)} KB\n          </p>\n        </div>\n        <div className=\"flex gap-2\">\n          <button\n            onClick={checkAll}\n            disabled={busy}\n            className=\"rounded-lg bg-sky-600 px-4 py-2 text-sm font-semibold hover:bg-sky-500 disabled:opacity-50\"\n          >\n            Buscar actualizaciones\n          </button>\n          <button\n            onClick={logout}\n            className=\"rounded-lg border border-slate-700 px-4 py-2 text-sm hover:bg-slate-800\"\n          >\n            Salir\n          </button>\n        </div>\n      </header>\n\n      {message && (\n        <p className=\"rounded-lg border border-emerald-800 bg-emerald-950/50 p-3 text-sm text-emerald-200\">\n          {message}\n        </p>\n      )}\n\n      <section className=\"grid gap-6 lg:grid-cols-[1.1fr_0.9fr]\">\n        <div className=\"rounded-2xl border border-slate-800 bg-slate-900/60 p-5\">\n          <h2 className=\"mb-4 font-semibold\">\n            {editingId ? `Editando script #${editingId}` : \"Nuevo script\"}\n          </h2>\n          <div className=\"grid gap-3 sm:grid-cols-2\">\n            <input\n              className={input}\n              placeholder=\"Nombre\"\n              value={form.name}\n              onChange={(e) => setForm({ ...form, name: e.target.value })}\n            />\n            <input\n              className={input}\n              placeholder=\"Version\"\n              value={form.version}\n              onChange={(e) => setForm({ ...form, version: e.target.value })}\n            />\n            <input\n              className={input}\n              placeholder=\"Autor\"\n              value={form.author}\n              onChange={(e) => setForm({ ...form, author: e.target.value })}\n            />\n            <select\n              className={input}\n              value={form.runAt}\n              onChange={(e) => setForm({ ...form, runAt: e.target.value })}\n            >\n              {[\"document-start\", \"document-body\", \"document-end\", \"document-idle\"].map((v) => (\n                <option key={v} value={v}>\n                  {v}\n                </option>\n              ))}\n            </select>\n            <textarea\n              className={`${input} sm:col-span-2`}\n              rows={2}\n              placeholder=\"Descripción\"\n              value={form.description}\n              onChange={(e) => setForm({ ...form, description: e.target.value })}\n            />\n            <textarea\n              className={`${input} sm:col-span-2`}\n              rows={2}\n              placeholder=\"@match, uno por linea\"\n              value={form.matches}\n              onChange={(e) => setForm({ ...form, matches: e.target.value })}\n            />\n            <textarea\n              className={`${input} sm:col-span-2`}\n              rows={2}\n              placeholder=\"@grant, uno por linea\"\n              value={form.grants}\n              onChange={(e) => setForm({ ...form, grants: e.target.value })}\n            />\n            <input\n              className={`${input} sm:col-span-2`}\n              placeholder=\"URL de origen (opcional, se sincroniza)\"\n              value={form.sourceUrl}\n              onChange={(e) => setForm({ ...form, sourceUrl: e.target.value })}\n            />\n            <textarea\n              className={`${input} sm:col-span-2`}\n              rows={10}\n              placeholder=\"Codigo del userscript\"\n              value={form.code}\n              onChange={(e) => setForm({ ...form, code: e.target.value })}\n            />\n          </div>\n\n          <div className=\"mt-4 flex flex-wrap items-center gap-3\">\n            <label className=\"flex items-center gap-2 text-sm text-slate-300\">\n              <input\n                type=\"checkbox\"\n                checked={form.obfuscateByDefault}\n                onChange={(e) => setForm({ ...form, obfuscateByDefault: e.target.checked })}\n              />\n              Servir ofuscado\n            </label>\n            <button\n              onClick={save}\n              disabled={busy}\n              className=\"rounded-lg bg-emerald-600 px-4 py-2 text-sm font-semibold hover:bg-emerald-500 disabled:opacity-50\"\n            >\n              {editingId ? \"Guardar cambios\" : \"Crear script\"}\n            </button>\n            {editingId && (\n              <button\n                onClick={() => {\n                  setEditingId(null);\n                  setForm({ ...emptyForm });\n                }}\n                className=\"text-sm text-slate-400 underline\"\n              >\n                Cancelar\n              </button>\n            )}\n          </div>\n        </div>\n\n        <div className=\"space-y-6\">\n          <div className=\"rounded-2xl border border-slate-800 bg-slate-900/60 p-5\">\n            <h2 className=\"mb-4 font-semibold\">Credenciales</h2>\n            <div className=\"space-y-3\">\n              <input\n                className={input}\n                type=\"password\"\n                placeholder=\"Contrasena actual\"\n                value={pinForm.currentPassword}\n                onChange={(e) => setPinForm({ ...pinForm, currentPassword: e.target.value })}\n              />\n              <input\n                className={input}\n                inputMode=\"numeric\"\n                maxLength={6}\n                placeholder=\"Nuevo PIN (6 digitos)\"\n                value={pinForm.newPin}\n                onChange={(e) =>\n                  setPinForm({ ...pinForm, newPin: e.target.value.replace(/\\D/g, \"\").slice(0, 6) })\n                }\n              />\n              <input\n                className={input}\n                type=\"password\"\n                placeholder=\"Nueva contrasena (opcional)\"\n                value={pinForm.newPassword}\n                onChange={(e) => setPinForm({ ...pinForm, newPassword: e.target.value })}\n              />\n              <button\n                onClick={saveCredentials}\n                disabled={busy}\n                className=\"rounded-lg bg-slate-700 px-4 py-2 text-sm font-semibold hover:bg-slate-600 disabled:opacity-50\"\n              >\n                Actualizar\n              </button>\n            </div>\n          </div>\n\n          <div className=\"rounded-2xl border border-slate-800 bg-slate-900/60 p-5\">\n            <h2 className=\"mb-4 font-semibold\">Instalacion en Tampermonkey</h2>\n            <p className=\"text-sm text-slate-400\">\n              Abre Tampermonkey → Utilidades → Importar desde URL y usa:\n            </p>\n            <code className=\"mt-2 block break-all rounded bg-slate-950 p-2 text-xs text-emerald-300\">\n              {\"{tu-dominio}\"}/api/scripts/{\"{id}\"}/download\n            </code>\n          </div>\n        </div>\n      </section>\n\n      <section className=\"overflow-hidden rounded-2xl border border-slate-800\">\n        <table className=\"w-full text-left text-sm\">\n          <thead className=\"bg-slate-900 text-xs uppercase text-slate-400\">\n            <tr>\n              <th className=\"p-3\">Script</th>\n              <th className=\"p-3\">Version</th>\n              <th className=\"p-3\">Origen</th>\n              <th className=\"p-3\">Actualizado</th>\n              <th className=\"p-3 text-right\">Acciones</th>\n            </tr>\n          </thead>\n          <tbody>\n            {items.map((script) => (\n              <tr key={script.id} className=\"border-t border-slate-800 hover:bg-slate-900/60\">\n                <td className=\"p-3\">\n                  <p className=\"font-medium\">{script.name}</p>\n                  <p className=\"text-xs text-slate-500\">\n                    {script.matches[0] ?? \"sin @match\"} · {(script.code.length / 1024).toFixed(1)} KB\n                  </p>\n                </td>\n                <td className=\"p-3 text-slate-300\">{script.version}</td>\n                <td className=\"p-3 text-xs text-slate-400\">\n                  {script.sourceUrl ? (\n                    <a\n                      className=\"text-sky-400 underline\"\n                      href={script.sourceUrl}\n                      target=\"_blank\"\n                      rel=\"noreferrer\"\n                    >\n                      sincronizado\n                    </a>\n                  ) : (\n                    \"local\"\n                  )}\n                </td>\n                <td className=\"p-3 text-xs text-slate-400\">\n                  {new Date(script.updatedAt).toLocaleString(\"es\")}\n                </td>\n                <td className=\"p-3 text-right text-xs\">\n                  <a\n                    className=\"mr-3 text-emerald-400 underline\"\n                    href={`/api/scripts/${script.id}/download`}\n                  >\n                    .user.js\n                  </a>\n                  <a\n                    className=\"mr-3 text-sky-400 underline\"\n                    href={`/api/scripts/${script.id}/download?obfuscate=1`}\n                  >\n                    ofuscado\n                  </a>\n                  <button className=\"mr-3 text-slate-300 underline\" onClick={() => edit(script.id)}>\n                    editar\n                  </button>\n                  <button className=\"text-red-400 underline\" onClick={() => remove(script.id)}>\n                    borrar\n                  </button>\n                </td>\n              </tr>\n            ))}\n            {items.length === 0 && (\n              <tr>\n                <td className=\"p-6 text-center text-slate-500\" colSpan={5}>\n                  Todavia no hay scripts guardados.\n                </td>\n              </tr>\n            )}\n          </tbody>\n        </table>\n      </section>\n    </div>\n  );\n}\n",
 "src/db/bootstrap.ts": "import { Pool } from \"pg\";\n\n/**\n * Crea (si no existen) todas las tablas de Tampervault.\n * Se puede ejecutar en el arranque: `await bootstrapDatabase()`.\n */\nexport async function bootstrapDatabase(): Promise<void> {\n  const connectionString = process.env.DATABASE_URL;\n  if (!connectionString) {\n    throw new Error(\"DATABASE_URL not set\");\n  }\n\n  const pool = new Pool({ connectionString });\n\n  try {\n    await pool.query(`\n      CREATE TABLE IF NOT EXISTS users (\n        id SERIAL PRIMARY KEY,\n        username TEXT UNIQUE NOT NULL,\n        password_hash TEXT NOT NULL,\n        pin_hash TEXT,\n        totp_secret TEXT,\n        created_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n\n      CREATE TABLE IF NOT EXISTS sessions (\n        id SERIAL PRIMARY KEY,\n        token_hash TEXT UNIQUE NOT NULL,\n        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        user_agent TEXT,\n        ip TEXT,\n        expires_at TIMESTAMP NOT NULL,\n        created_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n      CREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash);\n\n      CREATE TABLE IF NOT EXISTS pin_attempts (\n        id SERIAL PRIMARY KEY,\n        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        ip TEXT NOT NULL,\n        attempts INTEGER NOT NULL DEFAULT 0,\n        locked_until TIMESTAMP,\n        password_required_at TIMESTAMP,\n        created_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n      CREATE INDEX IF NOT EXISTS pin_attempts_user_id_idx ON pin_attempts(user_id);\n      CREATE INDEX IF NOT EXISTS pin_attempts_ip_idx ON pin_attempts(ip);\n\n      CREATE TABLE IF NOT EXISTS login_attempts (\n        id SERIAL PRIMARY KEY,\n        ip TEXT NOT NULL DEFAULT '',\n        username TEXT,\n        success BOOLEAN NOT NULL DEFAULT FALSE,\n        identifier TEXT,\n        attempts INTEGER NOT NULL DEFAULT 0,\n        locked_until TIMESTAMP,\n        last_attempt_at TIMESTAMP,\n        created_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n      CREATE INDEX IF NOT EXISTS login_attempts_ip_idx ON login_attempts(ip);\n      CREATE INDEX IF NOT EXISTS login_attempts_identifier_idx ON login_attempts(identifier);\n\n      CREATE TABLE IF NOT EXISTS login_events (\n        id SERIAL PRIMARY KEY,\n        identifier TEXT NOT NULL,\n        success BOOLEAN NOT NULL DEFAULT FALSE,\n        reason TEXT NOT NULL DEFAULT '',\n        created_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n      CREATE INDEX IF NOT EXISTS login_events_identifier_idx ON login_events(identifier);\n\n      CREATE TABLE IF NOT EXISTS scripts (\n        id SERIAL PRIMARY KEY,\n        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n        name TEXT NOT NULL,\n        namespace TEXT NOT NULL DEFAULT 'http://tampermonkey.net/',\n        version TEXT NOT NULL DEFAULT '1.0.0',\n        description TEXT NOT NULL DEFAULT '',\n        author TEXT NOT NULL DEFAULT '',\n        matches TEXT[] NOT NULL DEFAULT '{}'::text[],\n        grants TEXT[] NOT NULL DEFAULT '{}'::text[],\n        run_at TEXT NOT NULL DEFAULT 'document-idle',\n        update_url TEXT NOT NULL DEFAULT '',\n        download_url TEXT NOT NULL DEFAULT '',\n        code TEXT NOT NULL DEFAULT '',\n        obfuscate_by_default BOOLEAN NOT NULL DEFAULT FALSE,\n        code_hash TEXT NOT NULL DEFAULT '',\n        source_url TEXT,\n        last_check_at TIMESTAMP,\n        created_at TIMESTAMP NOT NULL DEFAULT NOW(),\n        updated_at TIMESTAMP NOT NULL DEFAULT NOW()\n      );\n    `);\n\n    console.log(\"[db] esquema creado/verificado\");\n  } finally {\n    await pool.end();\n  }\n}\n",
 "src/db/index.ts": "import { drizzle } from \"drizzle-orm/node-postgres\";\nimport { Pool } from \"pg\";\nimport * as schema from \"./schema\";\n\nconst connectionString = process.env.DATABASE_URL;\n\nif (!connectionString) {\n  throw new Error(\"DATABASE_URL is required\");\n}\n\nconst globalForDb = globalThis as typeof globalThis & {\n  __tampervaultPool?: Pool;\n};\n\nexport const pool =\n  globalForDb.__tampervaultPool ??\n  new Pool({\n    connectionString,\n    max: 10,\n    ssl: connectionString.includes(\"sslmode=require\")\n      ? { rejectUnauthorized: false }\n      : undefined,\n  });\n\nif (process.env.NODE_ENV !== \"production\") {\n  globalForDb.__tampervaultPool = pool;\n}\n\nexport const db = drizzle(pool, { schema });\nexport { schema };\n",
 "src/db/schema.ts": "import { sql } from \"drizzle-orm\";\nimport {\n  boolean,\n  index,\n  integer,\n  pgTable,\n  serial,\n  text,\n  timestamp,\n} from \"drizzle-orm/pg-core\";\n\nexport const users = pgTable(\"users\", {\n  id: serial(\"id\").primaryKey(),\n  username: text(\"username\").notNull().unique(),\n  passwordHash: text(\"password_hash\").notNull(),\n  pinHash: text(\"pin_hash\"),\n  totpSecret: text(\"totp_secret\"),\n  createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n});\n\nexport const sessions = pgTable(\n  \"sessions\",\n  {\n    id: serial(\"id\").primaryKey(),\n    tokenHash: text(\"token_hash\").notNull().unique(),\n    userId: integer(\"user_id\")\n      .notNull()\n      .references(() => users.id, { onDelete: \"cascade\" }),\n    userAgent: text(\"user_agent\"),\n    ip: text(\"ip\"),\n    expiresAt: timestamp(\"expires_at\").notNull(),\n    createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  },\n  (t) => [index(\"sessions_token_idx\").on(t.tokenHash)],\n);\n\nexport const pinAttempts = pgTable(\n  \"pin_attempts\",\n  {\n    id: serial(\"id\").primaryKey(),\n    userId: integer(\"user_id\")\n      .notNull()\n      .references(() => users.id, { onDelete: \"cascade\" }),\n    ip: text(\"ip\").notNull(),\n    attempts: integer(\"attempts\").notNull().default(0),\n    lockedUntil: timestamp(\"locked_until\"),\n    passwordRequiredAt: timestamp(\"password_required_at\"),\n    createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  },\n  (t) => [\n    index(\"pin_attempts_user_id_idx\").on(t.userId),\n    index(\"pin_attempts_ip_idx\").on(t.ip),\n  ],\n);\n\nexport const loginAttempts = pgTable(\n  \"login_attempts\",\n  {\n    id: serial(\"id\").primaryKey(),\n    ip: text(\"ip\").notNull().default(\"\"),\n    username: text(\"username\"),\n    success: boolean(\"success\").notNull().default(false),\n    identifier: text(\"identifier\"),\n    attempts: integer(\"attempts\").notNull().default(0),\n    lockedUntil: timestamp(\"locked_until\"),\n    lastAttemptAt: timestamp(\"last_attempt_at\"),\n    createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  },\n  (t) => [\n    index(\"login_attempts_ip_idx\").on(t.ip),\n    index(\"login_attempts_identifier_idx\").on(t.identifier),\n  ],\n);\n\nexport const loginEvents = pgTable(\n  \"login_events\",\n  {\n    id: serial(\"id\").primaryKey(),\n    identifier: text(\"identifier\").notNull(),\n    success: boolean(\"success\").notNull().default(false),\n    reason: text(\"reason\").notNull().default(\"\"),\n    createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  },\n  (t) => [index(\"login_events_identifier_idx\").on(t.identifier)],\n);\n\nexport const scripts = pgTable(\"scripts\", {\n  id: serial(\"id\").primaryKey(),\n  userId: integer(\"user_id\")\n    .notNull()\n    .references(() => users.id, { onDelete: \"cascade\" }),\n  name: text(\"name\").notNull(),\n  namespace: text(\"namespace\").notNull().default(\"http://tampermonkey.net/\"),\n  version: text(\"version\").notNull().default(\"1.0.0\"),\n  description: text(\"description\").notNull().default(\"\"),\n  author: text(\"author\").notNull().default(\"\"),\n  matches: text(\"matches\")\n    .array()\n    .notNull()\n    .default(sql`'{}'::text[]`),\n  grants: text(\"grants\")\n    .array()\n    .notNull()\n    .default(sql`'{}'::text[]`),\n  runAt: text(\"run_at\").notNull().default(\"document-idle\"),\n  updateUrl: text(\"update_url\").notNull().default(\"\"),\n  downloadUrl: text(\"download_url\").notNull().default(\"\"),\n  code: text(\"code\").notNull().default(\"\"),\n  obfuscateByDefault: boolean(\"obfuscate_by_default\").notNull().default(false),\n  codeHash: text(\"code_hash\").notNull().default(\"\"),\n  sourceUrl: text(\"source_url\"),\n  lastCheckAt: timestamp(\"last_check_at\"),\n  createdAt: timestamp(\"created_at\").notNull().defaultNow(),\n  updatedAt: timestamp(\"updated_at\").notNull().defaultNow(),\n});\n\nexport type User = typeof users.$inferSelect;\nexport type Script = typeof scripts.$inferSelect;\nexport type PinAttempt = typeof pinAttempts.$inferSelect;\n",
 "src/db/seed.ts": "import { db } from \"@/db\";\nimport { scripts, users } from \"@/db/schema\";\nimport { hashSecret } from \"@/lib/auth\";\n\nexport const DEFAULT_USERNAME = \"admin\";\nexport const DEFAULT_PASSWORD = \"tampervault\";\nexport const DEFAULT_PIN = \"123456\";\n\nlet seeded = false;\n\n/**\n * Crea el usuario por defecto la primera vez que se usa la app\n * sobre una base de datos vacia.\n */\nexport async function ensureSeed(): Promise<void> {\n  if (seeded) return;\n  seeded = true;\n\n  try {\n    const existing = await db.select({ id: users.id }).from(users).limit(1);\n    if (existing.length > 0) return;\n\n    const inserted = await db\n      .insert(users)\n      .values({\n        username: DEFAULT_USERNAME,\n        passwordHash: await hashSecret(DEFAULT_PASSWORD),\n        pinHash: await hashSecret(DEFAULT_PIN),\n      })\n      .returning({ id: users.id });\n\n    const userId = inserted[0]?.id;\n    if (!userId) return;\n\n    await db.insert(scripts).values({\n      userId,\n      name: \"Ejemplo: Hola Tampervault\",\n      version: \"1.0.0\",\n      description: \"Userscript de ejemplo para comprobar la instalacion\",\n      author: DEFAULT_USERNAME,\n      matches: [\"https://example.com/*\"],\n      grants: [\"GM_addStyle\"],\n      runAt: \"document-idle\",\n      code: `// ==UserScript==\\n// @name         Ejemplo: Hola Tampervault\\n// @version      1.0.0\\n// @match        https://example.com/*\\n// @grant        GM_addStyle\\n// @run-at       document-idle\\n// ==/UserScript==\\n\\n(function () {\\n  \"use strict\";\\n  GM_addStyle(\"body { outline: 4px solid #10b981; }\");\\n  console.log(\"[Tampervault] userscript activo\");\\n})();\\n`,\n    });\n\n    console.log(\"[seed] usuario y script de ejemplo creados\");\n  } catch (error) {\n    seeded = false;\n    console.error(\"[seed] fallo la inicializacion:\", error);\n  }\n}\n",
 "src/lib/auth.ts": "import {\n  createHash,\n  randomBytes,\n  scrypt as scryptCallback,\n  timingSafeEqual,\n} from \"node:crypto\";\nimport { promisify } from \"node:util\";\n\nconst scrypt = promisify(scryptCallback) as (\n  password: string,\n  salt: Buffer,\n  keylen: number,\n  options: { N: number; r: number; p: number },\n) => Promise<Buffer>;\n\nconst SCRYPT_N = 16384;\n\n/** Formato: scrypt$<N>$<salt-hex>$<hash-hex> */\nexport async function hashSecret(secret: string): Promise<string> {\n  const salt = randomBytes(16);\n  const derived = await scrypt(secret, salt, 64, { N: SCRYPT_N, r: 8, p: 1 });\n  return `scrypt$${SCRYPT_N}$${salt.toString(\"hex\")}$${derived.toString(\"hex\")}`;\n}\n\nexport async function verifySecret(\n  secret: string,\n  stored: string | null | undefined,\n): Promise<boolean> {\n  if (!stored) return false;\n  const parts = stored.split(\"$\");\n  if (parts.length < 4) return false;\n\n  const n = Number.parseInt(parts[1], 10);\n  if (!Number.isFinite(n) || n <= 0) return false;\n\n  try {\n    const salt = Buffer.from(parts[2], \"hex\");\n    const expected = Buffer.from(parts[3], \"hex\");\n    const derived = await scrypt(secret, salt, expected.length, { N: n, r: 8, p: 1 });\n    if (derived.length !== expected.length) return false;\n    return timingSafeEqual(derived, expected);\n  } catch {\n    return false;\n  }\n}\n\nexport function sha256(value: string): string {\n  return createHash(\"sha256\").update(value).digest(\"hex\");\n}\n\nexport function generateToken(): string {\n  return randomBytes(32).toString(\"base64url\");\n}\n\nexport function isValidPin(pin: unknown): pin is string {\n  return typeof pin === \"string\" && /^\\d{6}$/.test(pin);\n}\n\nexport function normalizeIp(header: string | null): string {\n  if (!header) return \"unknown\";\n  const first = header.split(\",\")[0]?.trim();\n  return first && first.length > 0 ? first : \"unknown\";\n}\n",
 "src/lib/obfuscate.ts": "/** Ofuscacion ligera sin dependencias: empaqueta el codigo en base64 ofuscado. */\nexport function obfuscateScript(code: string, header = \"\"): string {\n  const payload = Buffer.from(code, \"utf8\").toString(\"base64\");\n  const chunks = payload.match(/.{1,96}/g) ?? [];\n  const pieces = chunks.map((chunk) => `\"${chunk}\"`).join(\",\\n  \");\n\n  return `${header}\n/* Ofuscado por Tampervault */\n(function () {\n  \"use strict\";\n  var parts = [\n  ${pieces}\n  ];\n  function decode(b64) {\n    var chars = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n    var clean = b64.replace(/[^A-Za-z0-9+/=]/g, \"\");\n    var out = \"\";\n    var bits = 0;\n    var acc = 0;\n    for (var i = 0; i < clean.length; i++) {\n      var idx = chars.indexOf(clean.charAt(i));\n      if (idx === -1) continue;\n      acc = (acc << 6) | idx;\n      bits += 6;\n      if (bits >= 8) {\n        bits -= 8;\n        out += String.fromCharCode((acc >> bits) & 0xff);\n      }\n    }\n    return decodeURIComponent(escape(out));\n  }\n  new Function(decode(parts.join(\"\")))();\n})();\n`;\n}\n\nexport function buildUserscriptHeader(script: {\n  name: string;\n  namespace: string;\n  version: string;\n  description: string;\n  author: string;\n  matches: string[];\n  grants: string[];\n  runAt: string;\n  updateUrl: string;\n  downloadUrl: string;\n}): string {\n  const lines: string[] = [\"// ==UserScript==\"];\n  const push = (key: string, value: string) => {\n    if (value.trim()) lines.push(`// @${key}          ${value.trim()}`);\n  };\n\n  push(\"name\", script.name);\n  push(\"namespace\", script.namespace);\n  push(\"version\", script.version);\n  push(\"description\", script.description);\n  push(\"author\", script.author);\n  for (const match of script.matches) if (match.trim()) lines.push(`// @match         ${match.trim()}`);\n  for (const grant of script.grants) if (grant.trim()) lines.push(`// @grant         ${grant.trim()}`);\n  lines.push(`// @run-at        ${script.runAt}`);\n  if (script.updateUrl.trim()) lines.push(`// @updateURL     ${script.updateUrl.trim()}`);\n  if (script.downloadUrl.trim()) lines.push(`// @downloadURL   ${script.downloadUrl.trim()}`);\n  lines.push(\"// ==/UserScript==\");\n\n  return `${lines.join(\"\\n\")}\\n`;\n}\n",
 "src/lib/scripts.ts": "import { sha256 } from \"@/lib/auth\";\nimport { buildUserscriptHeader, obfuscateScript } from \"@/lib/obfuscate\";\nimport type { Script } from \"@/db/schema\";\n\nexport const RUN_AT_OPTIONS = [\n  \"document-start\",\n  \"document-body\",\n  \"document-end\",\n  \"document-idle\",\n] as const;\n\nfunction asString(value: unknown, fallback = \"\"): string {\n  return typeof value === \"string\" ? value : fallback;\n}\n\nexport function toStringList(value: unknown): string[] {\n  if (Array.isArray(value)) {\n    return value.map((v) => String(v).trim()).filter(Boolean);\n  }\n  if (typeof value === \"string\") {\n    return value\n      .split(/[\\n,]/)\n      .map((v) => v.trim())\n      .filter(Boolean);\n  }\n  return [];\n}\n\nexport function normalizeScriptInput(input: Record<string, unknown>) {\n  const runAt = asString(input.runAt, \"document-idle\");\n  return {\n    name: asString(input.name, \"Script sin nombre\").slice(0, 160),\n    namespace: asString(input.namespace, \"http://tampermonkey.net/\").slice(0, 300),\n    version: asString(input.version, \"1.0.0\").slice(0, 40),\n    description: asString(input.description).slice(0, 500),\n    author: asString(input.author).slice(0, 120),\n    matches: toStringList(input.matches),\n    grants: toStringList(input.grants),\n    runAt: (RUN_AT_OPTIONS as readonly string[]).includes(runAt) ? runAt : \"document-idle\",\n    updateUrl: asString(input.updateUrl).slice(0, 500),\n    downloadUrl: asString(input.downloadUrl).slice(0, 500),\n    code: asString(input.code),\n    sourceUrl: asString(input.sourceUrl).trim() || null,\n    obfuscateByDefault: input.obfuscateByDefault === true,\n  };\n}\n\nexport function scriptHash(code: string): string {\n  return sha256(code);\n}\n\nexport function renderUserScript(script: Script, obfuscated: boolean): string {\n  const header = buildUserscriptHeader(script);\n  return obfuscated ? obfuscateScript(script.code, header) : `${header}${script.code}\\n`;\n}\n\nexport async function fetchRemoteCode(\n  url: string,\n): Promise<{ ok: true; code: string } | { ok: false; error: string }> {\n  try {\n    const parsed = new URL(url);\n    if (parsed.protocol !== \"http:\" && parsed.protocol !== \"https:\") {\n      return { ok: false, error: \"Solo se permiten URLs http/https\" };\n    }\n    if ([\"localhost\", \"127.0.0.1\", \"0.0.0.0\"].includes(parsed.hostname)) {\n      return { ok: false, error: \"URL interna bloqueada por seguridad\" };\n    }\n\n    const response = await fetch(parsed.toString(), {\n      redirect: \"follow\",\n      signal: AbortSignal.timeout(10_000),\n      headers: { \"user-agent\": \"Tampervault/1.0 (+userscript-vault)\" },\n      cache: \"no-store\",\n    });\n\n    if (!response.ok) return { ok: false, error: `El servidor respondio ${response.status}` };\n\n    const text = await response.text();\n    if (text.length > 2_000_000) return { ok: false, error: \"El archivo supera 2 MB\" };\n    return { ok: true, code: text };\n  } catch (error) {\n    return { ok: false, error: (error as Error).message || \"Fallo la descarga\" };\n  }\n}\n\nexport function publicScript(script: Script) {\n  const { code, ...rest } = script;\n  return {\n    ...rest,\n    codeSize: code.length,\n    codePreview: code.slice(0, 400),\n    hasCode: code.trim().length > 0,\n  };\n}\n",
 "src/lib/session.ts": "import { cookies } from \"next/headers\";\nimport type { NextResponse } from \"next/server\";\nimport { and, eq, gt, lt } from \"drizzle-orm\";\nimport { db } from \"@/db\";\nimport { sessions, users, type User } from \"@/db/schema\";\nimport { generateToken, sha256 } from \"@/lib/auth\";\n\nexport const SESSION_COOKIE = \"tv_session\";\nconst SESSION_TTL_MS = 1000 * 60 * 60 * 12; // 12 horas\n\nexport async function createSession(\n  userId: number,\n  meta: { ip?: string; userAgent?: string } = {},\n): Promise<string> {\n  const token = generateToken();\n  const expiresAt = new Date(Date.now() + SESSION_TTL_MS);\n\n  await db.insert(sessions).values({\n    tokenHash: sha256(token),\n    userId,\n    ip: meta.ip ?? \"unknown\",\n    userAgent: meta.userAgent ?? \"unknown\",\n    expiresAt,\n  });\n\n  await db.delete(sessions).where(lt(sessions.expiresAt, new Date()));\n  return token;\n}\n\nexport function setSessionCookie(response: NextResponse, token: string): void {\n  response.cookies.set({\n    name: SESSION_COOKIE,\n    value: token,\n    httpOnly: true,\n    sameSite: \"lax\",\n    secure: process.env.NODE_ENV === \"production\",\n    path: \"/\",\n    maxAge: SESSION_TTL_MS / 1000,\n  });\n}\n\nexport function clearSessionCookie(response: NextResponse): void {\n  response.cookies.set({\n    name: SESSION_COOKIE,\n    value: \"\",\n    httpOnly: true,\n    sameSite: \"lax\",\n    secure: process.env.NODE_ENV === \"production\",\n    path: \"/\",\n    maxAge: 0,\n  });\n}\n\nexport async function getSessionToken(): Promise<string | null> {\n  const store = await cookies();\n  return store.get(SESSION_COOKIE)?.value ?? null;\n}\n\n/** Devuelve el usuario de la sesion activa o null. */\nexport async function getCurrentUser(): Promise<User | null> {\n  const token = await getSessionToken();\n  if (!token) return null;\n\n  const rows = await db\n    .select({ user: users })\n    .from(sessions)\n    .innerJoin(users, eq(users.id, sessions.userId))\n    .where(\n      and(eq(sessions.tokenHash, sha256(token)), gt(sessions.expiresAt, new Date())),\n    )\n    .limit(1);\n\n  return rows[0]?.user ?? null;\n}\n\nexport async function destroyCurrentSession(): Promise<void> {\n  const token = await getSessionToken();\n  if (!token) return;\n  await db.delete(sessions).where(eq(sessions.tokenHash, sha256(token)));\n}\n",
