import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  integer,
  pgTable,
  serial,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  pinHash: text("pin_hash"),
  totpSecret: text("totp_secret"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

export const sessions = pgTable(
  "sessions",
  {
    id: serial("id").primaryKey(),
    tokenHash: text("token_hash").notNull().unique(),
    userId: integer("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    userAgent: text("user_agent"),
    ip: text("ip"),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("sessions_token_idx").on(t.tokenHash)],
);

export const pinAttempts = pgTable(
  "pin_attempts",
  {
    id: serial("id").primaryKey(),
    userId: integer("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    ip: text("ip").notNull(),
    attempts: integer("attempts").notNull().default(0),
    lockedUntil: timestamp("locked_until"),
    passwordRequiredAt: timestamp("password_required_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("pin_attempts_user_id_idx").on(t.userId),
    index("pin_attempts_ip_idx").on(t.ip),
  ],
);

export const loginAttempts = pgTable(
  "login_attempts",
  {
    id: serial("id").primaryKey(),
    ip: text("ip").notNull().default(""),
    username: text("username"),
    success: boolean("success").notNull().default(false),
    identifier: text("identifier"),
    attempts: integer("attempts").notNull().default(0),
    lockedUntil: timestamp("locked_until"),
    lastAttemptAt: timestamp("last_attempt_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("login_attempts_ip_idx").on(t.ip),
    index("login_attempts_identifier_idx").on(t.identifier),
  ],
);

export const loginEvents = pgTable(
  "login_events",
  {
    id: serial("id").primaryKey(),
    identifier: text("identifier").notNull(),
    success: boolean("success").notNull().default(false),
    reason: text("reason").notNull().default(""),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (t) => [index("login_events_identifier_idx").on(t.identifier)],
);

export const scripts = pgTable("scripts", {
  id: serial("id").primaryKey(),
  userId: integer("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  namespace: text("namespace").notNull().default("http://tampermonkey.net/"),
  version: text("version").notNull().default("1.0.0"),
  description: text("description").notNull().default(""),
  author: text("author").notNull().default(""),
  matches: text("matches")
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  grants: text("grants")
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  runAt: text("run_at").notNull().default("document-idle"),
  updateUrl: text("update_url").notNull().default(""),
  downloadUrl: text("download_url").notNull().default(""),
  code: text("code").notNull().default(""),
  obfuscateByDefault: boolean("obfuscate_by_default").notNull().default(false),
  codeHash: text("code_hash").notNull().default(""),
  sourceUrl: text("source_url"),
  lastCheckAt: timestamp("last_check_at"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

